-- Client table LeagueInfo: all 373 rows of the 3.29.3c client. Written by scripts/dev/client-sql.ps1.
INSERT INTO "LeagueInfo" ("_row", "PanelVersion", "PanelId", "PanelImage", "HeaderImage", "Screenshots", "Description", "__col6", "TrailerVideoLink", "BackgroundImage", "__col9", "__col10", "PanelItems", "__col12", "__col13", "__col14", "__col15", "__col16", "__col17") VALUES
(0, 0, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Heading1', '[]', 'In Path of Exile: Delve, you will delve into the Azurite Mine''s infinite depths to extract treasure and discover its subterranean secrets.
Our latest expansion features an infinite dungeon and socketable currency items, as well as a bunch of new unique items, skill gems, balance changes, graphics engine improvements and more!', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(1, 0, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Heading2', '["Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel2/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel2/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel2/Screenshot3"]', 'Left untouched for over 250 years, the Azurite Mine has been consumed by a malevolent darkness that cast out the Eternal Empire. Niko, an inventor, has harnessed the power of Voltaxic Sulphite to create a machine called the Crawler that can pierce the darkness. Delve into the mine but don''t leave the Crawler''s light for long or you''ll be crushed by the darkness.
The Crawler will speed up if you get ahead of it.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(2, 0, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Heading3', '["Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel3/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel3/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel3/Screenshot3"]', 'The Azurite Mine is full of treasures for those brave enough to risk the darkness for short periods of time. Use flares to venture farther away from the Crawler''s path, and dynamite to destroy unstable walls which conceal even greater rewards.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(3, 0, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Heading4', '["Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel4/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel4/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel4/Screenshot3"]', 'Any Azurite you find in the mine can be traded to Niko at his base camp. In return, he offers to upgrade the Crawler and can sell you flares, dynamite and crafting materials to aid your exploration.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(4, 0, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Heading5', '["Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel5/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel5/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel5/Screenshot3"]', 'Deep in the Azurite Mine, you''ll discover many different biomes. As you delve even deeper, you may encounter lost cities from Wraeclast''s dark history. Each environment has its own monsters, bosses, encounters and rewards.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(5, 0, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Heading6', '[]', 'The ancient civilisations created special crafting items that can be socketed with fossils to modify their behaviour.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(6, 0, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Heading7', '[]', 'The Azurite Mine is Path of Exile''s first infinite dungeon. The deeper you delve, the harder the game gets. In Delve, you''ll find encounters that are much harder than end-game Maps. Your progress is only limited by the power of your character build. The Depth Ladder tracks who has delved the deepest into the mine.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(7, 0, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Heading8', '[]', 'Path of Exile: Delve includes ten powerful new or completely reworked skills, centered around two character archetypes: the Guardian and the Pathfinder. Play as a holy warrior who strikes down foes with lightning damage while benefiting teammates and minions, or as a chaotic archer who uses nature- and poison-based skills to pin and suffocate enemies.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(8, 0, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Heading9', '[]', 'A Path of Exile expansion is not complete without powerful new items to discover! Delve includes 7 new Divination Cards and 18 new Unique Items which have a focus on creating powerful new build opportunities.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(9, 0, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Heading10', '[]', 'In your travels across Wraeclast, you may very rarely discover a Timeworn Reliquary Key. This key will open a portal to the Timeworn Reliquary which contains one of 150 Unique Relics from past Path of Exile leagues.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(10, 0, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Delve/Heading11', '[]', 'We''re also launching two sets of Supporter Packs alongside Delve - the Shadowstalker and Dreadforge Packs. There are two price points available for each and they feature masses of points alongside new Armour Sets and other exclusive cosmetic microtransactions!', 0, '', '', 1, 0, '[]', '', '', '[]', '', 0, 0),
(11, 1, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Heading1', '[]', 'In Path of Exile: Betrayal, Jun Ortoi is investigating a mysterious organisation known as the Immortal Syndicate. Help her to manipulate their ranks, reveal the identities of their members, uncover their safehouses and take down their mastermind.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(12, 1, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Heading2', '["Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel2/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel2/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel2/Screenshot3"]', 'The Immortal Syndicate has four divisions, each with its own goals: Fortification, Transportation, Research and Intervention. In each area, you will encounter a Syndicate member. Other members can show up to aid their friends or sabotage their enemies. When the battle is complete, you must decide how to continue your investigation.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(13, 1, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Heading3', '[]', 'There are eighteen Syndicate members, each with their own personalities, friendships and rivalries that change as you manipulate the organisation. You will need to bargain, execute, interrogate and even induce them to betray each other in order to further the investigation.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(14, 1, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Heading4', '["Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel4/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel4/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel4/Screenshot3"]', 'Your goal is to gain intelligence leading to the captains of each division. Raid their safehouses to pillage their supplies and uncover the ultimate identity of the Immortal Syndicate''s mastermind.

Each Syndicate member stores different item types in the safehouse. High-ranked members will have better items. Each division has a different twist on item rewards. Manipulate the Syndicate, maneuvering certain members into positions that are going to be the most rewarding for you', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(15, 1, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Heading5', '[]', 'Members of the Immortal Syndicate can drop items with new Veiled Modifiers. Take these to Jun to Unveil the item and pick from one of three properties for the item to receive. As you Unveil specific modifiers, you learn the ability to craft these onto other items and can work towards unlocking higher-level versions of these properties.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(16, 1, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Heading6', '["Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel6/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel6/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel6/Screenshot3"]', 'As the Immortal Syndicate ascended in power, the old cohort of Forsaken Masters mysteriously vanished. In their absence, Einhar, Alva, Niko, Jun and Zana have risen as a new group of Masters to aid you. Their league content, including Delve and Incursion, has been added as core Path of Exile content. Bestiary has been reimagined and simplified; Einhar will handle the nets as you focus on hunting the beasts.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(17, 1, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Heading7', '[]', 'We have revamped the entire process of Mastercrafting, from the user interface to the way you acquire new crafting options. Individual Mastercrafting options are now unlocked by completing specific content, such as Incursion rooms or Delve encounters, rather than by grinding Master levels.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(18, 1, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Heading8', '["Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel8/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel8/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel8/Screenshot3"]', 'Hideouts, favour and decorations are now shared across all leagues. You can load and save your hideout templates and share them with other community members.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(19, 1, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Heading9', '["Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel9/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel9/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel9/Screenshot3"]', 'We have added four new maps to the Atlas of Worlds. These new maps are fleshed-out versions of fan-favourite tilesets from deep in Delve''s Azurite Mine. The entire Atlas of Worlds has been rearranged.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(20, 1, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Heading10', '["Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel10/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel10/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel10/Screenshot3","Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel10/Screenshot4","Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel10/Screenshot5","Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel10/Screenshot6"]', 'Alongside other balance improvements, Betrayal introduces ten new or revamped skills across three core character archetypes. These include several completely new types of skills, such as Brands and Banners.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(21, 1, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Betrayal/Panel12', '[]', 'Many of the 15 new unique items in Betrayal have Veiled mods, allowing you to customise the item more than ever before. Betrayal also includes five new Divination Cards, designed by our supporters.', 0, '', '', 1, 0, '[]', '', '', '[]', '', 0, 0),
(22, 2, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Heading1', '[]', 'In Path of Exile: Synthesis, you will encounter Cavas, recover his lost memories and chain them together to reach valuable rewards, new boss fights and crafting opportunities.

Our March expansion contains the Synthesis challenge league, new items, new gems, a complete rebalance of spells throughout Path of Exile, an integrated version of the Betrayal league and much, much more.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(23, 2, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Heading2', '["Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel2/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel2/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel2/Screenshot3"]', 'To help Cavas remember his past, you will find fragments of his decaying memories throughout Wraeclast. Fight your way through the monsters that inhabit his memories in order to activate stabilisers before the memories collapse around you.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(24, 2, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Heading3', '["Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel3/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel3/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel3/Screenshot3"]', 'Stabilised memory fragments can be pieced together to navigate the void in Cavas'' mind and reach his distant memories. But beware, these fragments can only be explored a limited number of times before they collapse completely, so plan your path carefully.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(25, 2, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Heading4', '["Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel4/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel4/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel4/Screenshot3"]', 'Within Cavas'' distant memories are many types of valuable rewards. As you progress deeper within the recesses of his darkest memories, his mind starts to synthesise encounters with dangerous and twisted manifestations.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(26, 2, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Heading5', '[]', 'Decaying memories yield Fractured Items with broken mods that are locked in place. While these are not generally useful as-is, you''ll find occasional Fractured Items that have excellent locked mods, resulting in much easier crafting.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(27, 2, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Heading6', '[]', 'In the Memory Nexus lies the Synthesiser, a powerful device that lets you destroy Fractured Items to create base types with custom implicit mods. These implicit mods are somewhat controllable by careful choice of input items to consume.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(28, 2, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Heading7', '["Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel7/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel7/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel7/Screenshot3"]', 'Synthesis also contains a complete balance overhaul of all spells in Path of Exile, six new Chaos and Holy spells and significant incentives for hand-casting including several new support gems.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(29, 2, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Heading8', '["Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel8/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel8/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel8/Screenshot3","Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel8/Screenshot4","Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel8/Screenshot5","Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel8/Screenshot6"]', 'The new Holy Spellcaster archetype features Path of Exile''s first Holy spells, including Divine Ire, Purifying Flame and Wave of Conviction. The Chaos Spellcaster archetype not only provides an easier introduction to Chaos spells with Soulrend, but adds many new tools to Path of Exile''s existing arsenal of Chaos spells.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(30, 2, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Heading9', '[]', 'In addition to Fractured Items, Synthesised Items and over a dozen new Divination Cards designed by our supporters, Path of Exile: Synthesis contains 16 powerful new unique items with a focus on impacting the way players play Path of Exile.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(31, 2, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Heading10', '[]', 'Synthesis also includes many other improvements: The content from December''s Betrayal expansion has been integrated into the core game, the layout of the Atlas of Worlds has shifted once again, and a lot of Path of Exile''s music has been overhauled. Check out the full patch notes in early March for more information!', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(32, 2, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Synthesis/Heading11', '[]', 'We''re also launching two sets of Supporter Packs alongside Synthesis - the Sunspire and Doomguard Packs. There are two price points available for each and they feature masses of points alongside new Armour Sets and other exclusive cosmetic microtransactions including new Hideouts!

Path of Exile: Synthesis will launch on March 8th (PST) on PC, March 11 on Xbox One and mid-March on PlayStation 4.', 0, '', '', 1, 0, '[]', '', '', '[]', '', 0, 0),
(33, 3, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/TrailerThumbnail', '', '[]', '', 0, 'http://web.poecdn.com/public/videos/LegionTrailer_EN.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(34, 3, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Heading1', '[]', 'Trapped for thousands of years in the Domain of Timeless Conflict, the mightiest military leaders of Wraeclast''s history have been fighting an eternal war. In Path of Exile: Legion, you will free their legions from the endless battle and defeat them in combat to earn their valuable rewards.

Path of Exile''s June expansion contains the Legion challenge league, new items, new gems, a game-wide overhaul of melee combat, and much, much more.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(35, 3, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Heading2', '["Art/2DArt/UIImages/Login/LeagueInfo/Legion/Panel2/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Legion/Panel2/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Legion/Panel2/Screenshot3"]', 'As you explore Wraeclast in the Legion league, you''ll discover Monoliths. Tag these to reveal an ancient conflict between multiple Legions, frozen in time. Untether monsters by dealing damage to them, but be prepared to fight those monsters when the effect of the Monolith wears off. As certain monsters are powerful and drop valuable items, Legion grants you full control over risk and reward.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(36, 3, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Heading3', '["Art/2DArt/UIImages/Login/LeagueInfo/Legion/Panel3/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Legion/Panel3/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Legion/Panel3/Screenshot3"]', 'Enemies from each of the five Legions drop Splinters which combine together to form an Emblem of that Legion. Place two or more Emblems from different Legions in a Map Device to gain access to the Domain of Timeless Conflict, where the eternal battle between those Legions rages. Unlock the upgraded Map Device in order to fight in the ultimate conflict between all five Legions.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(37, 3, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Heading4', '[]', 'Some Legion monsters display symbols indicating the specific items they drop. Skilled players will focus on freeing the monsters that maximise the type of rewards they are seeking. Certain monsters can drop Incubation Items, which modify a piece of equipment to guarantee a certain reward after you have killed a specific number of monsters.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(38, 3, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Heading5', '[]', 'From each of the five Legions, it''s possible to earn a special unique Jewel that can be socketed into your Passive Skill Tree. Each of the five jewels modifies nearby passive skills in different ways, providing completely new character customisation options if you are skilled enough to acquire one.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(39, 3, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Heading6', '[]', 'We''ve addressed most of the core issues with melee combat in Path of Exile. You can now cancel attack animations after they deal their damage. Movement skills are now all instant, and new low-level movement skills have been added for many classes. All melee attacks can now hit multiple adjacent enemies. The animation system has been overhauled, the monster targeting rules improved, and accuracy is no longer capped at 95%. There are more changes to melee combat than are possible to list here, but these changes plus a rebalance of most melee skills create an entirely new combat experience.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(40, 3, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Heading7', '["Art/2DArt/UIImages/Login/LeagueInfo/Legion/Panel7/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Legion/Panel7/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Legion/Panel7/Screenshot3"]', 'The new Blood and Sand Gladiator archetype can switch between Blood Stance and Sand Stance, dynamically modifying the function of new and existing skills. The new Rage Berserker archetype revamps the Rage system and introduces new skills that generate or consume Rage. These powerful archetypes and their new skills offer additional options for many other Path of Exile builds.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(41, 3, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Heading8', '[]', 'With all the melee combat improvements, players can now dodge out of the way of attacks easily. We have taken advantage of this by rebalancing monster attacks that used to have poor signalling to now have a wind-up. This rebalance extends to improving monster AI and boss fights throughout the early campaign.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(42, 3, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Heading9', '[]', 'Alongside 14 new Divination Cards, Path of Exile: Legion contains 12 new unique items for you to discover. In addition, we have chosen 15 existing unique items that are themed around Legion''s five armies and have rebalanced them so that they have become powerful rewards to find in the new league.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(43, 3, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Legion/Heading10', '[]', 'We''re also launching two sets of Supporter Packs alongside Legion - the Cult of Darkness and Blood Knight Packs. There are two price points available for each and they feature masses of points alongside new Armour Sets and other exclusive cosmetic microtransactions!

Path of Exile: Legion will launch on June 7th (PDT) on PC, and June 10 on Xbox One and PlayStation 4.', 1, '', '', 1, 0, '[]', '', '', '[]', '', 0, 0),
(44, 4, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/TrailerThumbnail', '', '[]', '', 0, 'http://web.poecdn.com/public/videos/BlightTrailer_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(45, 4, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Heading1', '[]', 'In Path of Exile: Blight, you must stop the spread of the deadly Blight by building towers to defend against monsters held in its thrall.

Our September expansion contains the Blight challenge league, three revamped balance archetypes with new skills and support gems, plenty of new items, two old leagues being integrated into the core game, and a focus on giving you more freedom to choose which aspects of Path of Exile''s content you play and when.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(46, 4, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Heading2', '["Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel2/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel2/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel2/Screenshot3"]', 'Sister Cassia is trying to stop the spread of the mind-controlling Blight by destroying Fungal Growths. When attacked, the Blight commands infected monsters to defend it. The monsters mindlessly follow the Blight''s tendrils, only attacking foes directly in their path. The infected are unusually tough, so you''ll need to build defensive towers to exploit each monster''s specific weaknesses. For each tendril lane you defend, a chest will appear with your rewards.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(47, 4, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Heading3', '[]', 'Sister Cassia''s arsenal contains towers that Chill, Shock, Stun, Burn, Summon, Empower, Petrify and Debilitate. Choose, place and upgrade these towers carefully to take advantage of both the terrain and the weaknesses of the infected monsters. These fast, bite-sized Tower Defense encounters combine Path of Exile''s intense action combat with the tactical fun of this popular genre.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(48, 4, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Heading4', '[]', 'Path of Exile''s end-game is not safe from the effects of the Blight either. Find Blighted Maps which contain gigantic Blight encounters with dozens of lanes and some of the league''s most valuable rewards.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(49, 4, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Heading5', '[]', 'Among other treasures, the Blight yields Oils which Sister Cassia can use to anoint your jewellery. Combine two Oils to enchant a Ring with a potent tower modifier. Combine three Oils to enchant your Amulet with any Notable Passive Skill from the Skill Tree. The twelve Oils vary considerably in rarity, with each combination of them granting a different result.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(50, 4, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Heading6', '[]', 'Four of the Unique Items exclusive to the Blight league form an armour set that can also be anointed with Notable Passives. Combined with an anointed Amulet, the wearer of this set can have up to five bonus Notable Passives active at once, unlocking countless new build possibilities.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(51, 4, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Heading7', '["Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel7/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel7/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel7/Screenshot3"]', 'You''re no longer forced to run every Master Mission as soon as you encounter it, or required to run arbitrary maps to complete your dailies. Significantly more of your Missions are now earned through map completion and they can be run later by talking to the Master in your hideout. Missions accumulate indefinitely, and you can run them whenever you have time, on whatever maps you choose.

We have also improved Betrayal''s rewards, made deeper depths easier to access in Delve, and integrated Legion and the boss fights from Synthesis into the core game.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(52, 4, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Heading8', '["Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel8/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel8/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel8/Screenshot3"]', 'Summoners are one of the most popular playstyles in Action RPGs. In Path of Exile: Blight we have significantly revamped many Summoner mechanics and the Witch''s Necromancer Ascendancy Class. We have buffed the per-gem-level progression of many minion types, added new support gems that allow you to fine-tune minion behaviour, revamped the Necromancer Ascendancy, introduced the Carrion Golem, added a high-level wand base type that can roll powerful minion mods and have made many other changes.

To support all the new skills that are available, we have added an additional bar of skill bindings.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(53, 4, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Heading9', '["Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel9/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel9/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel9/Screenshot3"]', 'The Poison Assassin, once the most dominant play style in Path of Exile, is returning (almost) to its glory days! Blight adds a new poison themed Support Gem and a suite of five potent new poison-themed Skill Gems, including Cobra Lash, which chains a poisoned projectile between your foes. The new Elusive mechanic, supported by a new Ascendancy notable, provides powerful defensive opportunities and a means of escape, while changes to the Perfect Agony Keystone Passive and multipliers for ailments from Critical Hits ensure the Poison Assassin gets his mark.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(54, 4, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Heading10', '["Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel10/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel10/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel10/Screenshot3"]', 'We often received feedback that Mines, though strong, felt clunky to use. In Blight, we have completely reworked Mine mechanics from the ground up. Thrown to a location rather than placed at your feet, Mines now deploy more quickly and detonate in sequence. Mine skills now also reward you for detonating long sequences. New and reworked Mine Support Gems, as well as the mobile Skitterbots, provide new avenues for explosive power. All these additions are further enhanced by changes to the Passive Skill Tree and the Saboteur Ascendancy Class.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(55, 4, '12', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Heading11', '[]', 'Alongside the Oils, Blighted Maps and new Jewellery Enchantments, Path of Exile: Blight contains 18 new Divination Cards, 16 new Skill and Support Gems, and 16 new Unique Items for you to discover. In addition, we have rebalanced 24 existing Unique Items, of which six have received substantial overhauls.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(56, 4, '13', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Panel12', 'Art/2DArt/UIImages/Login/LeagueInfo/Blight/Heading12', '[]', 'We''re also launching two sets of Supporter Packs alongside Blight - the Lich and Sentinel Packs. There are two price points available for each and they feature masses of points alongside new Armour Sets and other exclusive cosmetic microtransactions!

Path of Exile: Blight will launch on September 6th (PDT) on PC, and September 9 on Xbox One and PlayStation 4.', 1, '', '', 1, 0, '[]', '', '', '[]', '', 0, 0),
(57, 5, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Metamorph/TrailerThumbnail', '', '[]', '', 0, 'http://web.poecdn.com/public/videos/MetamorphTrailer_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(58, 5, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Metamorph/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Metamorph/Heading1', '[]', 'In the Metamorph league, you''ll meet a new NPC, Tane Octavius, a master alchemist who studied in Oriath. Exiled to Wraeclast for killing his teacher, Tane searches for what makes the self, by using his learned alchemical knowledge to assemble monster essences. He hopes to find a cure, or perhaps just the source, for what he calls the intrinsic darkness that led to his unforgivable violence.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(59, 5, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Metamorph/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Metamorph/Heading2', '["Art/2DArt/UIImages/Login/LeagueInfo/Metamorph/Panel2/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Metamorph/Panel2/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Metamorph/Panel2/Screenshot3"]', 'In each area you play in the Metamorph League, Tane will collect samples from selected monsters you have killed. Summon Tane to combine your choice of samples to create a formidable Metamorphic foe to defeat. Each sample contributes abilities to this boss, who wildly morphs from form to form during the encounter. With careful selection of samples, you control which abilities the boss has and what rewards it yields.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(60, 5, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Metamorph/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Metamorph/Heading3', '[]', 'Metamorph encounters can also drop Catalysts, a new type of currency item that adds quality to jewellery. There are many types of jewellery quality, each related to a set of mods. The quality value on a piece of jewellery scales up the magnitude of related mods on the item and can be consumed through crafting to increase the chances of rolling related mods.', 0, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(61, 5, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Metamorph/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Metamorph/Heading4', '["Art/2DArt/UIImages/Login/LeagueInfo/Metamorph/Panel4/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Metamorph/Panel4/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Metamorph/Panel4/Screenshot3"]', 'In the endgame of the Metamorph league, you can collect samples from Maps Bosses to create deadly Metamorphs that combine the powers, challenge and rewards of multiple bosses into very dangerous encounters.', 1, '', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(62, 5, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Metamorph/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Metamorph/Heading5', '[]', 'The Metamorph league is part of the larger Conquerors of the Atlas expansion, coming out on December 13 (PST) on PC, and the following week on Xbox One and PlayStation 4.', 0, '', '', 1, 0, '[]', '', '', '[]', '', 0, 0),
(63, 6, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/ThumbnailTrailer', '', '[]', '', 0, 'http://web.poecdn.com/public/videos/DeliriumTrailer_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(64, 6, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Heading1', '[]', 'A mysterious affliction has infiltrated your mind. As you touch the Mirror of Delirium, reality turns to mist and your worst nightmares emerge before your eyes.

Our March expansion contains the Delirium challenge league, the new Cluster Jewel system, new skills and support gems, powerful new items and further improvements to the Atlas endgame.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(65, 6, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Heading2', '["Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel2/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel2/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel2/Screenshot3"]', 'As the mists of Delirium consume you, new enemies emerge and existing foes gain savage talents. Delirium introduces dozens of lethal monster modifiers, many new bosses, and horrifying demons lurking within rare and unique monsters.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(66, 6, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Heading3', '["Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel3/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel3/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel3/Screenshot3"]', 'As you travel deeper into the Delirium, you''ll experience more numerous and challenging enemies with greater rewards. Will you let greed and hubris draw you into the madness?', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(67, 6, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Heading4', '["Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel4/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel4/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel4/Screenshot3"]', 'Nowhere is safe. Encounters you once mastered can now be played under the effects of Delirium, substantially ramping up their difficulty and rewards. If you''re daring, you can exploit Delirium to amplify past conflicts.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(68, 6, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Heading5', '[]', 'Orbs of Delirium can be applied to endgame maps to control how intense your Delirium is. Under the influence of an Orb, you are immediately plunged into Delirium for the entire duration of that map. A single Orb creates a challenging encounter, but up to five can be applied to a map for ultimate difficulty and rewards.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(69, 6, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Heading6', '[]', 'Search the deepest reaches of your Delirium for Splinters and combine them to create The Simulacrum. Enter its portal and try to survive the ultimate endgame Delirium challenge.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(70, 6, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Heading7', '[]', 'Extend your passive skill tree by placing a Cluster Jewel in one of its outermost sockets. With craftable mods that improve the passives generated, add one of 280 new notables, or even graft additional sockets for deeper nesting, Cluster Jewels let you grow your own passive tree.

Dropping from any monster in the Delirium League, these new Jewels are one of the most significant improvements to build customisation since the introduction of Ascendancy Classes.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(71, 6, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Heading8', '[]', 'Conquerors of the Atlas revitalised Path of Exile''s endgame experience. In Delirium, we have made Conqueror spawning deterministic, reintroduced Sextant vendor recipes, created extra incentives to reach higher Awakening levels, revamped Vaal side areas in maps, improved the Temple of Atzoatl, and more.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(72, 6, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Heading9', '["Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel9/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel9/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel9/Screenshot3"]', 'Delirium introduces four new Skill Gems and three new Support Gems. In classic Path of Exile style, we''ve focused on versatile designs that can complement many styles of gameplay.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(73, 6, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Heading10', '[]', 'In addition to the new Currency Items, Cluster Jewels, Gems and Endgame Simulacrum Maps, Path of Exile: Delirium introduces many new Divination Cards and Unique Items that provide new character build opportunities.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(74, 6, '12', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/Heading11', '[]', 'Alongside Path of Exile: Delirium, we''re also launching two sets of Supporter Packs - the Darkseer and Fateweaver Packs. There are two price points available for each and they each contain points, Armour sets and other cosmetic microtransactions!

Path of Exile: Delirium will launch on March 13 (PST) on PC and the following week on Xbox One and PlayStation 4.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 1, 0, '[]', '', '', '[]', '', 0, 0),
(75, 7, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/ThumbnailTrailer', '', '[]', '', 0, 'http://web.poecdn.com/public/videos/HarvestTrailer_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(76, 7, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/heading1', '[]', 'In Path of Exile: Harvest, Oshabi is cultivating the Sacred Grove, an ancient garden of mysterious power. Plant seeds that grow into dangerous enemies and craft their Lifeforce onto your items.

Our June expansion contains the Harvest challenge league, powerful new crafting options, eight new skills, two new support gems, revamps of Two-handed Weapons, Warcry skills, Brands, Slams and the Passive Skill Tree itself. We''ve also introduced 12 new unique items and rebalanced over 50 existing ones.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(77, 7, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/heading2', '["Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel2/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel2/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel2/Screenshot3"]', '<italic>{"It is beautiful, yes? I believe it to be older than the Eternal Empire. Older than the Vaal? I am not so sure. But it does not look like their work. I like to believe it is a work of my ancestral Azmeri. I was once blessed with a deep connection to the land. It would speak to me, and nourish me. But that connection was severed. And in turn, my tribe severed their connection to me. I was alone. Lost. The land spoke no more... until I found this place."} -- Oshabi', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(78, 7, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/heading3', '[]', 'Seek out the Seed Cache in every area you explore. Take its seeds through Oshabi''s portal to the Sacred Grove. Sow those seeds to grow dangerous and rewarding monsters. While most seeds grow easily, rarer high-tier ones require more careful planning but yield more valuable results.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(79, 7, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/heading4', '["Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel4/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel4/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel4/Screenshot3"]', 'When your monsters are ready for harvest, slaughter them and claim their Lifeforce. Every enemy you fight in the Sacred Grove is one you intentionally planted. Customise your combat around your character''s capabilities and what rewards you''re seeking.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(80, 7, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/heading5', '[]', 'Every monster you defeat in the Grove grants you a crafting option. Performing one of these powerful crafts consumes Lifeforce from the monsters you just harvested. In order to maximise your Lifeforce and hence crafting potential, you''ll want to take on as many monsters as you dare handle. Harvest Crafting provides powerful directed crafting to an extent that Path of Exile has never seen before.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(81, 7, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/heading6', '[]', 'As you build the ultimate garden, you''ll discover exotic seeds with specific needs that must be met in order to grow. Various pipes, storage tanks and dispersers can help you fertilise your garden with any remaining Lifeforce.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(82, 7, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/heading7', '["Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel7/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel7/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel7/Screenshot3"]', 'Oshabi speaks of the legend of three primordial beasts: Ersi, Janaar and Namharim. For those able to cultivate these rare seeds, the immense monsters that emerge can yield Harvest''s most valuable rewards.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(83, 7, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/heading8', '[]', 'The Passive Skill Tree has received many improvements including better support for some mechanics (for example, Two-handed Weapons or Rage) with both numeric buffs and entirely new clusters of passives. In addition, there are many new notable and keystones passives, which include both fan-favourites from Timeless Jewels and even some entirely new ones.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(84, 7, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/heading9', '["Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel9/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel9/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel9/Screenshot3"]', 'As part of our two-handed weapon improvements, several melee skills have been recategorised as slams. We''ve introduced a new slam skill and support gem. We''ve also revamped several existing slams with new visual effects, improved functionality and greater power for two-handed weapon users.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(85, 7, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/heading10', '["Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel10/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel10/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel10/Screenshot3"]', 'We''ve added four new Warcry skills and reworked three existing ones. Warcries now scale based on the power of nearby enemies rather than the quantity. Many Warcries also <italic>{exert} your attacks, increasing their power for a number of attacks.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(86, 7, '12', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/heading11', '["Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel11/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel11/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel11/Screenshot3"]', 'We''ve introduced three new Brands, one Brand support gem and have revamped existing Brands. We''ve made Brands a lot more versatile while also reviewing how their core mechanics work. Brand Recall no longer reigns supreme but is a useful tool alongside many new options.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(87, 7, '13', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel12', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/heading12', '[]', 'We''re introducing 12 new unique items and reworking over 50 existing ones.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(88, 7, '14', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel13', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/heading13', '[]', 'Delirium and Cluster Jewels are being integrated into the core Path of Exile experience! Because Delirium stacks with other league mechanics to make them more difficult and rewarding, the chance of encountering it rises exponentially with the number of other league mechanics in the area.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(89, 7, '15', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel14', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/heading14', '[]', 'Last week we released a Beta of our new Vulkan renderer which has greatly reduced stuttering and smoothed out game performance. This renderer has made a massive improvement for many players, and we aim to fix issues that other players have encountered before the release of Harvest. This new renderer comes alongside continued graphics technology improvements such as a new Bloom system that is used extensively in the Harvest league.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(90, 7, '16', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/Panel15', 'Art/2DArt/UIImages/Login/LeagueInfo/Harvest/heading15', '[]', 'We''re also launching two sets of Supporter Packs alongside Harvest - the Malice and Benevolence Packs. There are two price points available for each and they feature masses of points alongside new Armour Sets and other exclusive cosmetic microtransactions!

Path of Exile: Harvest will launch on June 19 (PDT) on PC, and June 24 on Xbox One and PlayStation 4.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Delirium/textbackground', 1, 0, '[]', '', '', '[]', '', 0, 0),
(91, 8, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/ThumbnailTrailer', '', '[]', '', 0, 'http://web.poecdn.com/public/videos/HeistTrailer_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(92, 8, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Heading1', '[]', 'In <italic>{Path of Exile: Heist}, you will hire skilled thieves to help you pull off risky Heists. Steal valuable artifacts to fund and train your crew as you plan towards the execution of a Grand Heist.

Our September expansion contains the Heist challenge league, nine new Skills and Support Gems, revamps of Curses, Steel Skills, and some Spells. Grand Heists offer exclusive new rewards such as Weapon and Body Armour Enchantments, Heist Trinkets, Alternate-quality Gems and Replica Unique Items.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(93, 8, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Heading2', '["Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel2/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel2/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel2/Screenshot3"]', 'Buy your passage to the Rogue Harbour where you''ll consort with a crew of thieves who offer nefarious services. Thirteen Rogues can be contracted to assist you with setting up or executing a Heist by filling roles such as transportation, lockpicking or demolition.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(94, 8, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Heading3', '["Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel3/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel3/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel3/Screenshot3"]', 'In order to execute a Heist, you need to know the location of a valuable Artifact and what defences safeguard it. Contracts containing these clues can be found throughout Wraeclast alongside coins with the mysterious emblem of the Rogue Harbour. Travel there and turn in these objects to hire the expertise you need for your Heist.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(95, 8, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Heading4', '["Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel4/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel4/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel4/Screenshot3"]', 'If you can''t escape the Heist, you''ll lose everything you stole while infiltrating the facility. You''ll need to support your Rogue while they bypass security in order to reach the vault. Be careful with how much commotion you cause, or you may trigger the alarm, causing the facility to be locked down. When this happens, it''s time to run.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(96, 8, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Heading5', '[]', 'Specialised items can be equipped to Rogues to make them stealthier, deadlier, and more adept at their roles. Like any other Path of Exile items, Rogue equipment can be crafted with currency items. A well-equipped crew is a great asset when undertaking the most difficult Heists.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(97, 8, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Heading6', '["Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel6/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel6/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel6/Screenshot3"]', 'The ultimate goal of a thief is to pull off a Grand Heist. This requires access to Blueprints that show where the vaults are located inside sprawling facilities. These elaborate jobs require masterful planning, purchasing additional intel about the facility, and hiring multiple Rogues to assist with their many obstacles. This planning can result in a huge pay-off as each vault has its own exclusive rewards.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(98, 8, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Heading7', '[]', 'One of the exclusive rewards you''ll be able to steal from Grand Heists are Trinkets, which go in their own new equipment slot. These magical items influence what rewards you''ll find from future Heists you run. Some of their modifiers affect the items dropped by enemies and chests, while others modify the rewards you could obtain from a Heist''s special reward chests.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(99, 8, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Heading8', '[]', 'Alternate Quality Gems come from Grand Heist reward rooms and provide even more depth for existing Skill and Support Gems. Each existing Path of Exile gem has up to three Alternate Quality versions which grant different quality bonuses than the original gems. Some simply increase the power of the gem while others entirely change which builds most benefit from the gem.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(100, 8, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Heading9', '[]', 'Other rewards you can claim from Grand Heists are Replica Unique Items and Experimented Base Types. Replica Unique items result from attempts to re-create unique items of legend, where the end product has a few crucial differences. They''re often appropriate for entirely different character builds than the original item. Experimented Base Types are a variety of new item base types that have exotic properties that differ from their core-game counterparts.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(101, 8, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Heading10', '[]', 'The final type of new reward available from Grand Heists is a selection of Weapon and Body Armour enchantments. These enchantments come on unnaturally-powerful rare items and affect the magnitude of modifiers on those items. Some of these enchantments are so powerful that they involve substantial drawbacks.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(102, 8, '12', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Heading11', '["Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel11/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel11/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel11/Screenshot3"]', 'We''ve added a new Curse-related skill and a new Curse support gem. The new Doom mechanic causes a self-cast Curse to increase in intensity over time until it expires. This works well in conjunction with the Impending Doom support, which causes an explosion of chaos damage when a linked curse ends. Curses have also received a new look.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(103, 8, '13', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel12', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Heading12', '["Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel12/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel12/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel12/Screenshot3"]', 'We''ve revamped Steel Skills by introducing Shards, deadly blades fragments that hover near your character. The Call of Steel Skill is available whenever you have a Steel skill equipped. It bursts Shards from the ground, providing more ammunition for Steel projectiles, and causes existing Shards to explode out of impaled enemies. We''ve also added one new Steel Skill and reworked both Shattering and Lancing Steel.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(104, 8, '14', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel13', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Heading13', '["Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel13/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel13/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel13/Screenshot3"]', 'Alongside the introduction of six new spells, we''ve reworked Discharge and Glacial Cascade. A goal with these new spells is that while they are powerful in a variety of character builds, they have additional benefits when self-cast.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(105, 8, '15', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel14', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Heading14', '[]', '<italic>{Path of Exile: Heist} also introduces over 25 new Unique Items, 12 new Divination Cards, a visual revamp to some skill effects and much more.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(106, 8, '16', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel15', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Heading15', '[]', 'We''re releasing Path of Exile for macOS alongside the Heist expansion! This version of Path of Exile is fully integrated into the main worldwide PC realm so you can access your existing accounts and microtransactions.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(107, 8, '17', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Panel16', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/Heading16', '[]', 'We''re also launching two sets of Supporter Packs alongside Heist - the Spellblade and Eagle Packs. There are two price points available for each and they feature masses of points, several exclusive microtransactions and a new type of character effect that charges up as you slay monsters.

<italic>{Path of Exile: Heist} will launch on September 18 (PDT) on PC, and September 23 on Xbox One and PlayStation 4.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Heist/textbackground', 1, 0, '[]', '', '', '[]', '', 0, 0),
(108, 9, 'Trailer', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/ThumbnailTrailer', '', '[]', '', 0, 'http://web.poecdn.com/public/videos/EchoesTrailer_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(109, 9, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Heading1', '[]', 'In <italic>{Path of Exile: Echoes of the Atlas}, you''ll gain even more control over your end-game Path of Exile experience by specialising each region of your Atlas with its own passive tree, crafting Watchstones to refine your rewards, selecting up to ten map bosses to face simultaneously and challenging the Atlas'' new pinnacle boss: The Maven.

Alongside this endgame content, you''ll perform dangerous and rewarding Rituals in the action-packed Ritual League, explore nineteen improved Ascendancy classes, discover powerful new items and much more.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(110, 9, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Heading2', '[]', '<italic>{When the Elder was sealed, entities far beyond the borders of the Atlas of Worlds took note and turned their attention in our direction. The first such visitor is an entity called The Maven. She is hungry to witness your fight for survival against the Atlas'' most dangerous foes. Accept her challenge to put your talents and mortality to the test. Should you prove worthy, she will offer you a taste of her vast power.}', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(111, 9, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Heading3', '["Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel3/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel3/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel3/Screenshot3"]', 'By slaying three map bosses in the Maven''s presence, you''ll earn an invitation to her realm where she will request that you defeat these bosses simultaneously. Having demonstrated your strength, she challenges you to defeat four bosses, then five, then six and finally ten at the same time. Only then can you take on the new pinnacle boss of the Atlas: the Maven herself.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(112, 9, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Heading4', '["Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel4/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel4/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel4/Screenshot3"]', 'Take control of your Atlas by unlocking regional passive trees which augment the content you encounter and rewards you receive while exploring those regions.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(113, 9, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Heading5', '[]', 'Echoes of the Atlas introduces three types of Craftable Watchstones. These valuable endgame items allow you to upgrade your Atlas and boost what types of rewards you find from maps. Players who are able to earn these powerful rewards will find that they are strictly better than regular Watchstones: they can be traded, don''t expire with use, and their benefits can stack.

Another new endgame reward, The Maven''s Orb, affects items that have two or more influence modifiers. When used on such an item, it randomly upgrades one of these influence modifiers and removes the others. If the modifier that''s being upgraded is already at the highest tier, it''ll upgrade to a new elevated tier.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(114, 9, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Heading6', '["Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel6/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel6/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel6/Screenshot3"]', 'Eleven new maps and challenging boss encounters have been added to the Atlas. These include unforgiving new locations such as the <italic>{Dry Sea, Forking River, Frozen Cabins} and <italic>{Grave Trough}.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(115, 9, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Heading7', '["Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel7/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel7/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel7/Screenshot3"]', '<italic>{Twisted spires of flesh, blood and sinew now stand scattered across Wraeclast''s landscape. Their origins and purposes unknown, they seemingly have a hunger for blood and death and are willing to richly reward those who can sate it.}

Ritual is a combat league that pits you against both the arcane powers of the Ritual Altar and escalating waves of monsters, enclosed within a Ritual Circle. Each successive Ritual in an area is harder and offers better rewards.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(116, 9, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Heading8', '[]', 'As you slay monsters during a Ritual, you''ll earn Tribute which can be spent on a variety of seductive items and rewards. Among these rewards, you may be offered new Ritual Base Types which pair very powerful implicit mods with challenging drawbacks. You can consume some Tribute to reroll the rewards offered or to defer selected ones until later.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(117, 9, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Heading9', '["Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel9/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel9/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel9/Screenshot3"]', 'In the end game, you can obtain tradeable Ritual vessels, which allow you to itemise the monsters from a ritual. You can place up to four vessels in the map device alongside a map to add their monsters to the rituals present in that map, substantially increasing both the difficulty and rewards of those Rituals.

Vessels also substantially increase monster density which can be very rewarding in maxed-out maps that have mechanics like Beyond and Delirium present.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(118, 9, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Heading10', '["Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel10/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel10/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel10/Screenshot3"]', 'In addition to numerically rebalancing every Ascendancy class, we''ve substantially reworked the Deadeye, Inquisitor and Elementalist. The aim of these reworks has been to redistribute power within each Ascendancy passive tree so that there are plenty of new ways to build powerful Path of Exile characters.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(119, 9, '12', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Heading11', '[]', 'One of the hallmarks of a Path of Exile expansion is its items! In addition to new craftable Watchstones, the Maven''s Orb and plenty of Ritual Base Types, we''ve also introduced the Hydrosphere Skill Gem, Trinity Support Gem, 13 new unique items and a slew of Divination Cards which have been designed by our supporters.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(120, 9, '13', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel12', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Heading12', '[]', 'Harvest has returned. Instead of having to plant and manage your own Sacred Grove, you will discover portals to established gardens with multiple sets of harvests ready to go. From each pair of options, carefully weigh the encounter difficulty against the crafting outcomes before making a choice. If you can slay the monsters that spawn, you''ll be rewarded with Lifeforce that can be used to greatly improve your items.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(121, 9, '14', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel13', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Heading13', '[]', 'In <italic>{Echoes of the Atlas}, Heist contracts drop from Act Six onwards. Rogues level up their skills faster, markers drop with higher stack sizes and quest contracts are now dropped for you at the next smuggler''s cache as soon as that quest is available.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(122, 9, '15', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Panel14', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/Heading14', '[]', 'In addition to the recently-released Core Packs, we''re also launching two new sets of Supporter Packs to celebrate the release of Echoes of the Atlas and the Ritual League: the Renegade and Faithsworn Packs. There are two price points available for each and they feature masses of points and several exclusive microtransactions like armour sets and character effects.

<italic>{Path of Exile: Echoes of the Atlas} will launch on January 15 (PST) on PC, and on January 20 on Xbox and PlayStation.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/Echoes/textbackground', 1, 0, '[]', '', '', '[]', '', 0, 0),
(123, 10, 'Trailer', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/ThumbnailTrailer', '', '[]', '', 0, 'http://web.poecdn.com/public/videos/UltimatumTrailer_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(124, 10, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Heading1', '[]', 'In <italic>{Path of Exile: Ultimatum}, you must undertake the trials of Chaos and choose whether to risk it all for ultimate power.

Our April expansion contains the Ultimatum challenge league, eight new Skill and Support Gems, improvements to Vaal Skills, an overhaul to past league reward systems, dozens of new items, and much more. We''ve also just released a new trailer and gameplay showcase for Path of Exile 2.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(125, 10, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Heading2', '[]', 'The ancient civilisation of the Vaal was built on sacrifice. They understood that in order to attain great power, great risks must be taken. On behalf of a Vaal entity known only as Chaos, the Trialmaster seeks to discover challengers who are willing to make immense sacrifices in the pursuit of power. As you survive each of his challenges, will you risk it all and accept his next Ultimatum?', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(126, 10, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Heading3', '["Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel3/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel3/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel3/Screenshot3"]', 'The Trialmaster offers you a reward and a challenge with three difficulty modifiers to choose from. If you succeed in his trial, you may claim your reward. However, you''ll be presented with an Ultimatum: leave with your spoils, or attempt more challenging encounters for more valuable rewards. But be careful how many trials you undertake - if you fail, you''ll lose everything you''ve earned so far.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(127, 10, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Heading4', '["Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel4/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel4/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel4/Screenshot3"]', 'In the endgame, Inscribed Ultimatums indicate an offering you must bring to the Trialmaster''s Domain. If you''re able to succeed at the inscribed challenge, the Trialmaster will reward you with an item of roughly double value. But if you fail, you forfeit the offering that you put on the line. Inscribed Ultimatums come with a challenging assortment of Ultimatum difficulty modifiers and can be traded to other players.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(128, 10, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Heading5', '[]', 'As the difficulty of the Trialmaster''s encounters escalates, so too do the rewards. In addition to some of Path of Exile''s most valuable items, you might be offered new Ultimatum-exclusive Unique items. We''ve designed this league to be very compatible with party play - each player gets their own rewards, can vote on difficulty modifiers and can choose whether they want to risk the next round or not.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(129, 10, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Heading6', '[]', 'The Vaal Reliquary Key can drop from anywhere in Path of Exile and opens a portal to the Vaal Reliquary. This ancient vault contains a chest with a special foil version of a Vaal-themed Unique item, dropped with equal weighting. Due to the value and power level of the items contained within, this is the rarest Reliquary Key ever added to Path of Exile.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(130, 10, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Heading7', '["Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel7/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel7/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel7/Screenshot3","Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel7/Screenshot4","Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel7/Screenshot5","Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel7/Screenshot6"]', 'We''ve introduced eight new Skill and Support gems that are themed around the concept of blood: sacrificing life for power. These gems open up even more possibilities for characters built around staying on low life, the threshold for which has been increased to 50%. We''ve also rebalanced Vaal Skills and increased the number of souls gained from damaging Unique enemies.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(131, 10, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Heading8', '[]', 'In Ultimatum we''ve buffed the core drop pool with more valuable items to find from any content in Path of Exile. We''ve bolstered the core drop pool with new currency items, secret vendor recipes, a selection of powerful league-specific uniques (including Headhunter!), new Atlas base types, and have made Act bosses worth farming again. But that''s just the start. Almost every other reward system in Path of Exile has been improved as well.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(132, 10, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Heading9', '[]', 'We''ve made several improvements to the rewards in The Lord''s Labyrinth. You can now see enchantment outcomes before you pick them and a choice of three specific helmet enchantments are offered in the Eternal Labyrinth. The Emperors'' jewels that used to be awarded for fastest daily Labyrinth runs can now drop rarely from the Labyrinth''s reward chests. We have introduced two new Labyrinth-specific Unique items. You can now consume an Offering to the Goddess in the map device to open portals directly to a random trial.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(133, 10, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Heading10', '[]', 'When you slay Betrayal''s Mastermind, her Immortal Syndicate Members now drop their rewards at one tier higher than their current tier. A valuable fourth tier of rewards has been added to allow this, and a few of the best existing rewards have been moved to that tier. Veiled Modifier crafting now unlocks faster and modifiers that are unveiled on items are now more powerful than their crafted counterparts. A new Betrayal-specific unique item can now drop from the Mastermind.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(134, 10, '12', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Heading11', '[]', 'Perandus Coin drops have been rebalanced and can now be used to purchase a wider range of items from Cadiro. We''ve rebalanced Essences so that they are generally stronger and have allowed Screaming Essences to reroll rare items. There are four new unique Abyss Jewels, which alongside other rebalanced Abyss jewels are now best found from Abyss chests. We''ve also introduced Abyss Scarabs.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(135, 10, '13', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel12', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Heading12', '[]', 'We have added new Beastcrafts, such as ones that can add mods to maps or influenced items. It''s no longer possible to imprint items that have been split (a process which is now limited to once per item). Incursion has received many improvements to its rewards, including the ability to turn your Temple of Atzoatl into an item that can be traded to other players.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(136, 10, '14', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel13', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Heading13', '[]', 'Alongside new Blight, Metamorph and Delirium Incubators, we''ve modernised other Incubator rewards. We have introduced Blight-themed Scarabs and two new Catalysts. Corrupted Blighted Maps can drop the new Tainted Oil which allows anointment of corrupted items. Chests in Blighted Maps now benefit from the map''s item quantity value.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(137, 10, '15', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel14', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Heading14', '[]', 'Ritual has become a core game mechanic, spawning in 8% of maps, which is the new game-wide rate for past league mechanics. We''ve improved Atziri''s rewards by buffing her exclusive Sacrificial Garb base type and adding new Unique items that only she can drop.

There are also nerfs to a few past leagues that are currently too powerful. Talismans no longer drop using the well-rolled mod system, but their anointments can be changed using a Tainted Oil. Some Harvest crafts have been removed or restricted, but Harvest now spawns more frequently and the Heart of the Grove encounter is now a tradeable map fragment.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(138, 10, '16', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/PoE2NewTrailerThumbnail', '', '[]', '', 0, 'http://web.poecdn.com/public/videos/PoE2Trailer2_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(139, 10, '17', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel16', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Heading16', '[]', 'Path of Exile 2''s first gameplay showcase at ExileCon was set in the dark forests of the Island of Ogham. Our latest showcase takes place in the ancient dunes of the Vastiri Desert and uses two new weapon types - Spears and Crossbows - to demonstrate Path of Exile 2''s next-generation action combat.

Path of Exile 2 does not have a release date yet, but we are targeting a Closed Beta in 2022.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(140, 10, '18', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Panel17', 'Art/2DArt/UIImages/Login/LeagueInfo/Ultimatum/Heading17', '[]', 'In addition to the recently-released Core Packs, we''re also launching two new sets of Supporter Packs to celebrate the release of the Ultimatum League: the Silver Crescent and Imperial Sun packs. There are two price points available for each and they feature masses of points and several exclusive microtransactions like armour sets, helmet skins, weapon skins and more.

<italic>{Path of Exile: Ultimatum} will launch on April 16 (PDT) on PC and Mac, and on April 21 on Xbox and PlayStation.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 1, 0, '[]', '', '', '[]', '', 0, 0),
(141, 11, 'Trailer', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/ExpeditionThumbnailTrailer', '', '[]', '', 0, 'http://web.poecdn.com/public/videos/ExpeditionTrailer_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(142, 11, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Heading1', '[]', 'In <italic>{Path of Exile: Expedition}, you will join the Kalguuran expedition, excavate their lost relics and undead using chains of explosives, then barter, deal and gamble these relics with their merchants.

Our July expansion contains the Expedition challenge league, four new NPC traders, nineteen new skill and support gems, new base item types and unique items. We''ve also made massive balance changes to make Path of Exile more challenging, including a full rework of the flask system. And finally, Path of Exile: Royale makes its long-awaited return!', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(143, 11, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Heading2', '["Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Screenshots/Panel2/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Screenshots/Panel2/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Screenshots/Panel2/Screenshot3"]', 'The Kalguur are using explosives to excavate their ancestors'' settlements throughout Wraeclast. Overwhelmed by the dangers they unearth, they require your violent services. You must strategically lay a chain of explosives and detonate them, defeating the undead that rise. Tactical planning is essential, as you must decide what to prioritise in the excavation, carefully balancing your temptation and capabilities.

You may choose to unearth chests full of valuable rewards, or to revive the undead husks of Kalguuran explorers and their treasures. It pays to be mindful of the mysterious Remnants of Kalguuran settlements scattered around the site. When detonated, their modifiers significantly increase the difficulty and reward of your Expedition.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 1, '[]', '', '', '[]', '', 0, 0),
(144, 11, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Heading3', '["Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Screenshots/Panel3/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Screenshots/Panel3/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Screenshots/Panel3/Screenshot3"]', 'After retrieving ancient runed artifacts from the Expedition sites you may trade them to the Kalguuran merchants who seek to recover them. Each is interested in different varieties of artifacts and offers a unique trading experience for you to try to take advantage of: gambling, bartering, upselling or exchanging.

Gwennen, the Gambler, believes not in luck but that good fortune comes only to those who believe hard enough. Rog, the Dealer, is a fearful but earnest man who just wants to make a deal. Tujen, the Haggler, is open to negotiating but has a short temper. Dannig is the leader of the Expedition and wants to facilitate your trades with his countrymen.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 1, '[]', '', '', '[]', '', 0, 0),
(145, 11, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Heading4', '["Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Screenshots/Panel4/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Screenshots/Panel4/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Screenshots/Panel4/Screenshot3"]', 'During your Expeditions, you may discover Logbooks. These ancient books chronicle the locations that the ancient Kalguur visited. Find a Logbook, craft its mods like a map, bring it to Dannig and choose a location for your next Expedition. These Expeditions are much larger than regular ones and harbour many mysteries to explore, if you dare.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(146, 11, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Heading5', '["Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Screenshots/Panel5/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Screenshots/Panel5/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Screenshots/Panel5/Screenshot3"]', 'While planning your chain of explosives in a Logbook Expedition, you should consider detonating various destructible objects. Such obstacles might be blocking secret passages leading to ancient, terrifying bosses and their valuable treasures.

These treasures include unique items and base types that introduce a new defensive mechanic called Ward. When you''re hit, your Ward is completely depleted and reduces the damage dealt to you by that amount. A few seconds later, your ward replenishes itself and you''re protected from the next hit.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 1, '[]', '', '', '[]', '', 0, 0),
(147, 11, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Heading6', '[]', 'Alongside Expedition, we are revitalising Path of Exile''s build metagame by both introducing many new playstyles and augmenting existing builds with powerful new tools. We''ve created 19 new skill and support gems that are designed around the themes of each Ascendancy Class.

A new skill inspired by the Ascendant, Spectral Helix throws out a spectral copy of your weapon which spirals outwards from you.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(148, 11, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Heading7', '[]', 'Inspired by the Marauder''s Juggernaut, Berserker and Chieftain Ascendancy classes, we''ve created the Boneshatter and Rage Vortex skill gems and the Earthbreaker support gem. Boneshatter strikes enemies with a forceful blow. If this attack stuns an enemy, it releases a powerful shockwave with area based on the stun''s duration. As you use Boneshatter more, it deals more and more damage to enemies and to yourself. Rage Vortex consumes your Rage to unleash a whirling vortex that rapidly hits enemies within its range. The Earthbreaker Support summons an Ancestral Totem that uses any supported Slam Skill.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(149, 11, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Heading8', '[]', 'Inspired by the Duelist''s Champion, Gladiator and Slayer Ascendancy classes, we''ve created the Defiance Banner and Shield Crush skill gems and the Behead support gem. Defiance Banner is a new defensive tool that can be used to increase your armour and evasion while reducing the critical strike chance of nearby enemies. Shield Crush swipes your shield towards your enemies and sends out forceful waves of damage based on the stats of your shield. The Behead Support can only support Strike skills and is basically like a mini-Headhunter. When your supported Strike slays a rare enemy, you''ll steal one of its modifiers at random for 20 seconds.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(150, 11, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Heading9', '[]', 'Inspired by the Ranger''s Raider, Pathfinder and Deadeye Ascendancy classes, we''ve created the Storm Rain and Explosive Concoction skill gems and the Focused Ballista support gem. Storm Rain fires arrows that stick into the ground. These arrows periodically pulse with lightning damage that arcs to nearby arrows. Focused Ballista causes your Ballistas to focus fire on your target and only fire when you do. Explosive Concoction must be used unarmed and throws an explosive projectile at your target. You can enhance this explosion by consuming charges from Ruby, Sapphire or Topaz flasks.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(151, 11, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Heading10', '[]', 'Inspired by the Shadow''s Assassin, Saboteur and Trickster Ascendancy classes, we''ve created the Ambush, Blade Trap and Voltaxic Burst skill gems. Ambush is a new Blink skill which teleports you to an enemy, blinds them and exerts your next one-handed melee attack. When you use Blade Trap, you throw out a mechanical device with two copies of your weapon attached. These blades spin rapidly in a circle a set number of times, dealing damage to anything they pass through. Voltaxic Burst grants a buff which counts down to zero, at which point it detonates, sending out a damaging lightning and chaos explosion. Enemies slain by this explosion will also explode dealing lightning and chaos damage based on a portion of their life.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(152, 11, '12', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Heading11', '[]', 'Themed around the Witch''s Occultist, Elementalist and Necromancer Ascendancy classes, we''ve created the Forbidden Rite, Eye of Winter and Summon Reaper skill gems. Forbidden Rite fires a barrage of exploding chaos projectiles at nearby enemies while also inflicting damage on you. The Eye of Winter is a large projectile that fires out a torrent of cold projectiles in a spiral formation as it travels. Summon Reaper is a new minion that feeds off your other minions (literally). It inflicts bleed on enemies and can be commanded to attack specific locations.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(153, 11, '13', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Panel12', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Heading12', '[]', 'Inspired by the Templar''s Hierophant, Guardian and Inquisitor Ascendancy classes, we''ve created the Manabond, Absolution and Battlemage''s Cry Skills. Manabond creates a rune that explodes, dealing more damage or having more area of effect, based on the current state of your mana pool. When Absolution''s damaging shockwave kills an enemy, it creates a Sentinel of Absolution which also casts its own shockwaves. Battlemage''s Cry taunts nearby enemies and exerts subsequent attacks, causing them to trigger a linked spell on your next melee hit.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(154, 11, '14', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Panel13', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Heading13', '[]', 'Expedition is Path of Exile''s 30th release since Closed Beta. In almost every update, we provide new ways to improve your characters, more effective skills to use, and ways to craft better and more powerful items. The power level of end-game Path of Exile characters has increased tenfold since Launch. From this expansion onwards, we are working to restore some of the challenge that Path of Exile is known for.

In addition to a substantial Flask Rework, we''re reducing the power level of pure-damage support gems, making triggered skills cost mana, tweaking the most powerful movement skills and making the enemies in Path of Exile''s first act much more dangerous. Our work to improve the level of challenge in Path of Exile will continue across subsequent expansions.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(155, 11, '15', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Panel14', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Heading14', '[]', 'We have substantially reworked Path of Exile''s Flask System with the goal of reducing the level of permanent player power that flasks grant and promoting considered flask choices that incentivise interactive gameplay. The new Instilling Orb allows you to modify your utility flasks so that they trigger on certain conditions. The Enkindling Orb provides a boost to your utility flasks in exchange for preventing charge gain while they''re active. We have also reworked many flasks and introduced new Gold and Corundum Flasks.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(156, 11, '16', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Panel15', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Heading15', '[]', 'A few years ago we launched a rough but playable Battle Royale mode as an April Fool''s joke. While we intended it to be short-lived, the Path of Exile community has demanded its return. Today we''re launching the new and improved Path of Exile: Royale which has many new features and separate balance from Path of Exile''s core game.

This mode is available now on PC for only two days and will be available again during weekends for the duration of the Expedition League. We will continue to iterate on its balance throughout this time, releasing updates between the weekly play sessions.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(157, 11, '17', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Panel16', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Heading16', '[]', 'Royale now has its own Passive Skill Tree which lets you focus on what matters most for low-level PvP combat. We''ve also rebalanced a selection of skills and iconic unique items from throughout the game so that they''re appropriate for Royale play. There''s an improved spectator mode, leaderboard and many other new features. If you can kill all other players in your session, you''ll win the new Rhoa Feast Hideout Decoration that upgrades in appearance as you win more matches. Visit the website for more information about Path of Exile: Royale!', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(158, 11, '18', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Panel17', 'Art/2DArt/UIImages/Login/LeagueInfo/Expedition/Heading17', '[]', 'We''re launching two new sets of Supporter Packs to celebrate the release of the Expedition League: the Soulkeeper and Aesir packs. There are three price points available for each and they feature masses of points and several exclusive microtransactions like armour sets, weapon skins, apparition portals and more!

<italic>{Path of Exile: Expedition} will launch on July 23 (PDT) on PC and Mac, and on July 28 on Xbox and PlayStation.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 1, 0, '[]', '', '', '[]', '', 0, 0),
(159, 12, 'Trailer', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/TrailerThumbnails/ScourgeThumbnailTrailer', '', '[]', '', 0, 'http://web.poecdn.com/public/videos/ScourgeTrailer_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(160, 12, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Heading1', '[]', 'In <italic>{Path of Exile:} Scourge, you must fill the Blood Crucible with the blood of your enemies then shift into an alternate Wraeclast where an apocalyptic event rages, in order to slay powerful demons and craft potent items.

Our October expansion contains the Scourge challenge league, new skill gems, a rework to the passive skill tree, improvements to the Atlas endgame, new aspirational endgame content, new guild features, new unique items and much, much more. ', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(161, 12, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Heading2', '["Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Screenshots/Panel2/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Screenshots/Panel2/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Screenshots/Panel2/Screenshot3"]', 'A mysterious figure appears out of nowhere, trying to escape from something you can''t see. She hands you a rusty-looking device called the Blood Crucible and urges you to implant it into your body.

The Blood Crucible fills with the blood of monsters you slay. Once it reaches a certain threshold, you''re able to activate the device. This will instantly thrust you into a parallel reality, an alternate Wraeclast overrun by demons known as The Scourge. The more blood you have collected, the longer you can stay shifted into the parallel Wraeclast. But the longer you stay, the more damage you''ll take.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 1, '[]', '', '', '[]', '', 0, 0),
(162, 12, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Heading3', '[]', 'You can place an item inside the Blood Crucible. While you are killing the Scourge, it absorbs corruption from the alternate Wraeclast and focuses it onto the item. After enough kills, your item can be transformed, corrupting it and granting it a pair of Scourged Modifiers. One of these is a powerful beneficial mod and one is a detrimental mod that may or may not strongly affect your build. 

If you get a combination you''re unhappy with, your item is not ruined. By putting it back in the Blood Crucible, and killing even more monsters in the alternate Wraeclast, you can transform it a second or third time, potentially getting a better pair of mods that overwrite the first set. ', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Scourge/OblivionKeep.itemblob","Metadata/LeagueInfoPanelItems/Scourge/RageUrge.itemblob"]', '', '', '[]', '', 0, 0),
(163, 12, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Heading4', '[]', 'As you slay the Scourge, the Blood Crucible gains experience and can level up. You can allocate its skill points in its own passive skill screen, which allows it to specialise in many aspects including unlocking additional item slots, faster item transformation, better transformation outcomes and the ability to transform unique items. ', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(164, 12, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Heading5', '[]', 'In the Atlas of Worlds, you may find the Dream Furnace, a device that grants you the ability to place Maps in the Blood Crucible, alongside your equipment. When a Map absorbs enough corruption and transforms, it gains a beneficial and detrimental effect in the same way that a piece of equipment does, but can also gain a modifier that changes the behaviour of Scourge league in that map entirely. 

Maps can be transformed up to ten times, increasing their risk and reward substantially each time. When a Map is transformed a second or subsequent time, there''s a chance that the new beneficial or detrimental modifiers stack alongside the existing ones, enhancing their power, or a chance that new modifiers are added. ', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(165, 12, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Heading6', '["Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Screenshots/Panel6/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Screenshots/Panel6/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Screenshots/Panel6/Screenshot3"]', 'The Scourge expansion includes a rework of Path of Exile''s iconic passive skill tree. Despite these large changes, the tree is intended to still feel familiar to existing players. We have rebalanced all passive skills, consolidated their power around their primary function, and moved many niche stats to a new system: <italic>{Passive Skill Masteries.}

When you allocate the first Notable passive skill in a cluster, a Mastery appears. Allocating a skill point to this Mastery allows you to pick from a list of advanced stats that match the theme of the cluster. This new system both makes the tree more understandable and gives you more freedom for how you plan your passive skills. We have also rebalanced a few keystone passives, changed the locations of some and added six new keystones to the tree.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 1, '[]', '', '', '[]', '', 0, 0),
(166, 12, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Heading7', '["Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Screenshots/Panel7/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Screenshots/Panel7/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Screenshots/Panel7/Screenshot3"]', '<italic>{Path of Exile: Scourge} introduces many new skill gems designed to create new build archetypes. Convert your Energy Shield into Energy Blades, summon a giant Tornado that is powered up by your own projectiles, rewind your character''s timeline with Temporal Rift, throw Poisonous Concoctions at your enemies and help your friends with six new party-oriented Link skills. ', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Scourge/Tornado.itemblob","Metadata/LeagueInfoPanelItems/Scourge/PoisonousConcoction.itemblob","Metadata/LeagueInfoPanelItems/Scourge/SoulLink.itemblob"]', '', '', '[]', '', 0, 0),
(167, 12, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Heading8', '[]', 'Early next year, we will release a huge overhaul of Path of Exile''s Atlas of Worlds endgame in the 3.17 expansion. In the meantime, though, the Scourge release speeds up how quickly you can set up and progress through your Atlas.

We have reduced the number of regions from 8 to 4, which reduces the number of Watchstones required from 32 to 16. We have also reduced the number of maps on the Atlas to 100 plus the unique maps. We''ve rebalanced the bonuses for completing content so that by the time your Atlas is fully unlocked, you''ll receive a slightly higher level of benefit than you did before. ', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(168, 12, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Heading9', '["Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Screenshots/Panel9/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Screenshots/Panel9/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Screenshots/Panel9/Screenshot3"]', 'Path of Exile: Scourge introduces new Uber versions of a lot of endgame content, which allow you to challenge your best characters on the hardest content we have ever made. Three of the new unique items that are introduced in this expansion can only be found from specific Uber content.

Flawless Breachstones allow access to a new tier of Breach Domain. Blighted maps can now drop Blight-ravaged Maps which can be anointed up to nine times (with up to three of each type of anointment). Delirium''s Simulacrum has been extended with additional challenging waves. New Unrelenting Emblems can be combined with Timeless Emblems to increase the difficulty of the Domain of Timeless Conflict. Delve has been rebalanced and now offers greater challenge, greater reward and more frequent boss encounters. ', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 1, '["Metadata/LeagueInfoPanelItems/Scourge/UnrelentingTimelessMarakethEmblem.itemblob","Metadata/LeagueInfoPanelItems/Scourge/ChayulasFlawlessBreachstone.itemblob"]', '', '', '[]', '', 0, 0),
(169, 12, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Heading10', '["Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Screenshots/Panel10/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Screenshots/Panel10/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Screenshots/Panel10/Screenshot3"]', 'The Scourge expansion contains a long-awaited set of quality-of-life improvements for Path of Exile''s guilds! Guild Stashes have been improved to support all the features of personal stash tabs, such as ctrl+clicking, affinities and rearrangement. We have also implemented guild versions of all the various exotic stash tabs such as Currency Tabs and Map Tabs. 

We''ve introduced Guild Hideouts, where you and your friends can have meetings, hang out, and access the map device as though it were your own. As part of our hideout improvements, we have removed the Favour system entirely. Now, all non-microtransaction hideout decorations are available in unlimited quantities for everyone to decorate their personal and guild hideouts with.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 1, '[]', '', '', '[]', '', 0, 0),
(170, 12, '12', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Heading11', '[]', 'In Path of Exile: Scourge, we''ve done a lot of balance work improving flasks, ailment mitigation, general character defenses and elemental damage over time. We have made some changes to how stacking auras and curses works, and have buffed most Awakened Support Gems. Check out the full changes in the Path of Exile: Scourge Patch Notes. ', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(171, 12, '13', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Panel12', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Heading12', '[]', 'In this expansion, we''re integrating the Expedition league into Path of Exile''s core game and are retiring the Perandus league. You''ll start finding Expeditions from Act 6 onwards, and there''s a base 8% chance that you''ll encounter it in each Map.

We have made some improvements to Expedition, most notably changing Expedition Artifacts so that they are not tradeable items anymore, which means they are automatically picked up during the encounters. ', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(172, 12, '14', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Panel13', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Heading13', '[]', 'In addition to six new unique items, 13 new Divination Cards and five new Currency Items, we have also added two new socket styles for colourblind users and have made changes to how currency items drop so that fewer clicks are required to pick them all up.

We''re also teaming up with Twitch Rivals to run another Path of Exile: Royale tournament, this time with a new twist. Tune in on October 28 to watch your favourite streamer compete for their share of a $30,000 prize pool. ', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Scourge/UulNetolsVow.itemblob","Metadata/LeagueInfoPanelItems/Scourge/Mageblood.itemblob","Metadata/LeagueInfoPanelItems/Scourge/TaintedChromaticOrb.itemblob","Metadata/LeagueInfoPanelItems/Scourge/TaintedOrbofFusing.itemblob","Metadata/LeagueInfoPanelItems/Scourge/TaintedJewellersOrb.itemblob","Metadata/LeagueInfoPanelItems/Scourge/SacredOrb.itemblob","Metadata/LeagueInfoPanelItems/Scourge/TaintedBlessing.itemblob","Metadata/LeagueInfoPanelItems/Scourge/StasisPrison.itemblob"]', '', '', '[]', '', 0, 0),
(173, 12, '15', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Panel14', 'Art/2DArt/UIImages/Login/LeagueInfo/Scourge/Heading14', '[]', 'We''re launching two new sets of Supporter Packs to celebrate the release of the Scourge League: the Dread and Liege packs. There are three price points available for each and they feature masses of points and several exclusive microtransactions like armour sets, weapon skins, portal effects and more! To add extra value, we have also added $5 worth of extra points to the two lower tiers of packs.

Path of Exile: Scourge will launch on October 22 (PDT) for PC and Mac, and on October 27 for Xbox and PlayStation. ', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 1, 0, '[]', '', '', '[]', '', 0, 0),
(174, 13, 'Trailer', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/TrailerThumbnails/SiegeThumbnail', '', '[]', '', 0, 'http://web.poecdn.com/public/videos/SiegeTrailer_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(175, 13, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Heading1', '[]', 'In <italic>{Path of Exile: Siege of the Atlas}, two new Eldritch Horrors threaten to consume the Atlas of Worlds. Join Commander Kirac''s militia and defend the Atlas and Wraeclast itself against these celestial foes.

This large endgame expansion contains new Atlas systems, pinnacle bosses, one gigantic Atlas passive skill tree, Eldritch implicit endgame crafting, new unique items, the Archnemesis Challenge league and much more.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(176, 13, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Heading2', '["Art/2DArt/UIImages/Login/LeagueInfo/Siege/screenshots/Panel2/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Siege/screenshots/Panel2/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Siege/screenshots/Panel2/Screenshot3"]', 'Having assumed responsibility for the defense of the Atlas, Commander Kirac has established a base in the Karui Archipelago with several map devices. He has heard rumours of your prowess and invites you to join his militia in order to scout the Atlas to learn about threats to Wraeclast. You encounter the Maven and discover that two new Eldritch Horrors are here: The Searing Exarch and The Eater of Worlds. They must be stopped before they consume everything.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(177, 13, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Heading3', '["Art/2DArt/UIImages/Login/LeagueInfo/Siege/screenshots/Panel3/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Siege/screenshots/Panel3/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Siege/screenshots/Panel3/Screenshot3"]', 'The Searing Exarch and The Eater of Worlds are the most powerful beings that Wraeclast has ever seen. The path to defeating them involves exploring many influenced maps and slaying their formidable subordinates, The Black Star and The Infinite Hunger, yielding valuable rewards.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(178, 13, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Heading4', '[]', 'Most Atlas mechanics have been reworked with a goal of creating deeper systems that are easier to understand. Regions have been removed, so your Atlas specialisation affects every map you run. Where you''d previously collect 16 Watchstones, you must now earn four Voidstones which let you raise the tier of all maps on your Atlas until they are uniformly tier 16. Sextants can apply to Voidstones and be itemised and traded. Commander Kirac offers a large variety of Atlas objectives that add valuable content to your maps.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Archnemesis/ChargedCompass.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/SingularScoutingReport.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/OtherworldlyScoutingReport.itemblob"]', '', '', '[]', '', 0, 0),
(179, 13, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Heading5', '["Art/2DArt/UIImages/Login/LeagueInfo/Siege/screenshots/Panel5/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Siege/screenshots/Panel5/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Siege/screenshots/Panel5/Screenshot3"]', 'Say goodbye to regional Atlas Passive Trees and hello to one gigantic Atlas-wide Passive Tree with over 600 skills to specialise in. Every map as well as various Atlas quests you complete will earn you an Atlas skill point. In addition to the best skills from the regional trees, we have created many completely new ones that let you choose your own level of risk and reward for Atlas content.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(180, 13, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Heading6', '[]', 'The Searing Exarch and The Eater of Worlds each have a powerful set of Eldritch Implicit Modifiers, which can be imbued onto items using Eldritch Embers and Eldritch Ichor, respectively. Although this process replaces existing implicit mods, it''s possible to have both types of Eldritch Implicits on an item at the same time.

You can use an Orb of Conflict to manipulate the tiers of these modifiers on your item, within the six tiers of modifiers available. When applied, the Orb randomly increases the tier of one modifier and lowers the tier of the other. The new Eldritch Chaos Orb, Eldritch Exalted Orb and Eldritch Orb of Annulment can manipulate the prefixes or suffixes of an item depending on whether The Searing Exarch or The Eater of Worlds has a higher Eldritch modifier on it.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Archnemesis/OrbofConflict.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/EldritchChaosOrb.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/EldritchExaltedOrb.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/EldritchOrbofAnnulment.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/LesserEldritchEmber.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/GreaterEldritchEmber.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/GrandEldritchEmber.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/ExceptionalEldritchEmber.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/LesserEldritchIchor.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/GreaterEldritchIchor.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/GrandEldritchIchor.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/ExceptionalEldritchIchor.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/ApocalypseWard.itemblob"]', '', '', '[]', '', 0, 0),
(181, 13, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Heading7', '[]', 'The four new pinnacle Atlas bosses each have their own drop pools of new unique items to find. There are more than a dozen in total and they represent some of the most powerful unique items we have introduced to Path of Exile yet, enabling exciting new character build opportunities.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Archnemesis/AshesoftheStars.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/DissolutionoftheFlesh.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/PolaricDevastation.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/ForbiddenFlame.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/ForbiddenFlesh.itemblob"]', '', '', '[]', '', 0, 0),
(182, 13, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Heading8', '["Art/2DArt/UIImages/Login/LeagueInfo/Siege/screenshots/Panel8/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Siege/screenshots/Panel8/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Siege/screenshots/Panel8/Screenshot3"]', 'In the Archnemesis league, you''ll build your own Rare boss fights by applying new monster modifiers to petrified monsters, found throughout every area. These modifiers add dangerous behaviours to their targets but also imbue them with valuable rewards. Each subsequent petrified monster you imbue within an area keeps all of the previous modifiers applied, allowing you to build some extremely difficult and rewarding encounters. There are over 60 new boss modifiers to discover, more than half of which can be created by combining other modifiers in specific recipes to unlock the most powerful and rewarding modifiers.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Archnemesis/toxic.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/echoist.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/berserker.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/mirror-image.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/flame-walker.itemblob","Metadata/LeagueInfoPanelItems/Archnemesis/innocence-touched.itemblob"]', '', '', '[]', '', 0, 0),
(183, 13, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Heading9', '[]', 'Aside from the usual buffs and nerfs of every Path of Exile expansion, our balance focus in Siege of the Atlas has been on improving two build archetypes that were previously under-performing and bringing them up to the level of other popular archetypes. In particular, we''re focusing on buffing hand-cast spells and hit-based bow builds. You can find more detail about this in its balance manifesto or in the full patch notes.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(184, 13, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Heading10', '[]', 'Alongside the launch of Siege of the Atlas, we''re hosting a competitive event where players will race in the Archnemesis Hardcore Solo Self-found League to be the first to defeat a trio of bosses: The Maven, The Searing Exarch and the Eater of Worlds. We''ll be providing more details on the event and its prizes in the coming week.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(185, 13, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Heading11', '[]', 'We''re introducing two new specialised stash tabs which allow you to store up to 500 Gems or Flasks respectively. The introduction of these stash tabs also allows players to set affinities for these items on any other stash tabs that will hold them.

The Gem Tab lets you filter between Red, Green, Blue and White gems. You can also select whether these are sorted by criteria such as current gem level, required level or quality. The Flask Tab lets you filter between Life, Mana, Hybrid, Utility and Unique flasks. You can also select whether these are sorted by item level, base type or quality.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(186, 13, 'SupporterPacks', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Panel12', 'Art/2DArt/UIImages/Login/LeagueInfo/Siege/Heading12', '[]', 'We''re launching two new sets of Supporter Packs to celebrate the release of Siege of the Atlas and the Archnemesis League. These are the Wyrm and Emberkeep series. There are three price points available for each and they feature masses of points and several exclusive microtransactions like Apparition Effects, Armour Sets, Weapon Skins, and more.

<italic>{Path of Exile: Siege of the Atlas} will launch on February 4 (PST) for PC and Mac, and on February 9 for Xbox and PlayStation.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 1, 0, '[]', '', '', '[]', '', 0, 0),
(187, 14, 'Trailer', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/TrailerThumbnail', '', '[]', '', 0, 'http://web.poecdn.com/public/videos/SentinelTrailer_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(188, 14, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Heading1', '[]', 'In <italic>{Path of Exile: Sentinel}, ancient constructs have been unearthed across Wraeclast. You will harness the power of these Sentinels to control your level of risk and reward on the battlefield.

Our May expansion contains the Sentinel challenge league, 20 atlas keystone passives, seven uber boss fights, new pinnacle unique items, revamped monster modifiers, game controller support, new quality of life features, a revamped challenge system and much more.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(189, 14, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Heading2', '[]', 'In this league, you will uncover and collect Sentinels and take advantage of their great power. When deployed, they follow you for a short time and empower your enemies, greatly increasing both their difficulty and reward.

There are three classes of Sentinels. Stalker Sentinels empower a moderate number of enemies in sequence as you encounter them. Pandemonium Sentinels empower a wide swath of monsters at once in a quick burst. Apex Sentinels only empower rare or unique enemies but have a very strong effect.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Sentinel/ThreateningObsidianApexSentinelofDanger.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/LingeringBronzeStalkerSentinel.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/EmberstoneStalkerSentineloftheStash.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/OminousMachine.itemblob"]', '', '', '[]', '', 0, 0),
(190, 14, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Heading3', '[]', 'The Sentinel Controller is like a runic circuit board that powers your Sentinels and allows you to customise their behaviour. It initially provides enough power to use one Sentinel per area but as you progress, it will gain enough power to support three.

You will place filaments on the Controller to dictate which runic nodes its power flows through. You can freely move filaments around at any time. As you gain more power, it will automatically flow to the next nodes you have connected. Use this Controller to establish specific behaviour for your Sentinel loadout that works well with your desired build.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(191, 14, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Heading4', '["Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/screenshots/Panel4/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/screenshots/Panel4/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/screenshots/Panel4/Screenshot3"]', 'When your Sentinels run out of charge, they can be combined together with a Power Core to assemble a new, fully-charged Sentinel that inherits properties from both of the husks you disassembled. This hybrid Sentinel may also gain special properties such as an exclusive variant base type or modifiers that can only come from the assembly process.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Sentinel/PowerCore.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/TransformingPowerCore.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/AmplifyingPowerCore.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/AugmentingPowerCore.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/EerieGuardian.itemblob"]', '', '', '[]', '', 0, 0),
(192, 14, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Heading5', '[]', 'As you travel through Wraeclast, you may uncover or assemble Unique Sentinels. These valuable Sentinels behave in very specialised and powerful ways. For example, The Basilisk causes a wide area-of-effect blast that has a petrification effect on monsters. The Hollow-Eyed Skull is basically a Headhunter in Sentinel form. There are also a set of Unique Sentinels that empower specific Atlas Map Bosses, causing them to become much more dangerous and rewarding.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Sentinel/TheHollowEyedSkull.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/TheBasilisk.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/TheAngelofVengeance.itemblob"]', '', '', '[]', '', 0, 0),
(193, 14, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Heading6', '[]', 'In the Sentinel League, you may find a new type of rare currency: Recombinators. These allow you to apply the Sentinel Assembly process to your actual items, taking any two pieces of equipment from the same item class and combining them together. While the results are unpredictable, this process could merge the best elements of each item, potentially adding an exclusive new modifier, to create something of unprecedented power.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Sentinel/ArmourRecombinator.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/WeaponRecombinator.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/JewelleryRecombinator.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/DominationTether.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/RageCircle.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/HypnoticPelt.itemblob"]', '', '', '[]', '', 0, 0),
(194, 14, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Heading7', '["Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/screenshots/Panel7/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/screenshots/Panel7/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/screenshots/Panel7/Screenshot3"]', 'The best thing about the Siege of the Atlas expansion was the control it gave you over your endgame experience, through the Atlas-wide Passive Tree. We have doubled down on this by introducing 20 new keystone passives to the Atlas tree that allow you to dramatically customise how you play Path of Exile''s endgame.

You can make it so that only your favoured maps will drop, gain bonuses for not modifying your maps with fragments, convert unwanted maps or scarabs into random ones, control how offensive or defensive monsters you encounter in maps are and even turn off specific past leagues to improve the chances of encountering the content you enjoy the most.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(195, 14, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Heading8', '[]', 'Six of the new keystones on the Atlas Passive Tree create uber versions of Path of Exile''s pinnacle boss fights: Venarius, Sirus, The Maven, The Searing Exarch, The Eater of Worlds, The Shaper and The Uber Elder. But be warned: only allocate one of these keystones if you are prepared to face the hardest content Path of Exile has to offer and to earn some of its most seductive rewards.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Sentinel/AwakenedEmpowerSupport.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/AwakenedEnlightenSupport.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/AwakenedEnhanceSupport.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/ThreadofHope.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/ForbiddenFlame.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/ForbiddenFlesh.itemblob"]', '', '', '[]', '', 0, 0),
(196, 14, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Heading9', '[]', 'In our Siege of the Atlas boss kill event, several of our most experienced players earned the right to design unique items, which are being introduced in Path of Exile: Sentinel! These new unique items drop from The Infinite Hunger, The Black Star, The Shaper, The Uber Elder, The Maven and Sirus.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Sentinel/TheBurdenofTruth.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/EchoesofCreation.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/TheEternalStruggle.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/CalloftheVoid.itemblob","Metadata/LeagueInfoPanelItems/Sentinel/ImpossibleEscape.itemblob"]', '', '', '[]', '', 0, 0),
(197, 14, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Heading10', '[]', 'Alongside the launch of Path of Exile: Sentinel, we''re hosting an event where players will compete in the Hardcore Solo Self-Found Sentinel league to be the first to kill the new uber pinnacle bosses. Winners will immortalise themselves forever by designing an endgame unique item or divination card that will be added to Path of Exile in August''s 3.19 expansion. Keep an eye on the upcoming news for more details.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(198, 14, '12', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Heading11', '[]', 'We''re going to try something new with character balance in this expansion. We''re intentionally making no changes to character power. That means no nerfs, no buffs, nothing. Every single build and build guide made for Siege of the Atlas will work exactly the same in Sentinel. You can start planning your league starter right now, with full confidence about exactly how it''s going to play.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(199, 14, '13', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Panel12', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Heading12', '["Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/screenshots/Panel12/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/screenshots/Panel12/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/screenshots/Panel12/Screenshot3"]', 'We''re replacing all existing monster modifiers with the mods that we introduced in the Archnemesis League, which all have a great impact on combat and are easy to identify at a glance. Magic packs share one modifier between them while Rare monsters typically have two modifiers, and can rarely spawn with more. Multiple synergistic mods can create quite dangerous situations in combat.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(200, 14, '14', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Panel13', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Heading13', '[]', 'We''ve implemented support for game controllers in the PC version of Path of Exile. This also means that if you''re lucky enough to already have a Steam Deck, you can play Path of Exile on the go!', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(201, 14, '15', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Panel14', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Heading14', '[]', 'In this expansion, we''ve added several small quality of life features that should help to enhance the ease of your game experience. For example, it''s now much easier to add maps to your Favoured Maps list on the Atlas. We''ve also added settings which allow you to define who is able to access the portals in your hideout. There are several other new features that we''ll reveal over the coming week.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(202, 14, '16', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Panel15', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Heading15', '[]', 'The challenge system in the Sentinel League is much harder but more rewarding than that of the past 21 leagues. Early challenges have been condensed so that their rewards unlock at 6 and 12 completions, rather than at 12 and 24. There are far more difficult objectives available to challenge Path of Exile''s best players and there are ten different rewards you can unlock, which comprise two complete armour sets, each with a pair of wings.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(203, 14, '17', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Panel16', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Heading16', '["Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/screenshots/Panel16/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/screenshots/Panel16/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/screenshots/Panel16/Screenshot3"]', 'Kirac''s Vault returns for the Sentinel League with a brand new set of exclusive unique item skins. Purchasing access to Kirac''s Vault allows you to claim these exclusive rewards as you complete map objectives in the Sentinel League. These exclusive skins apply to popular unique items that can be found in Path of Exile''s endgame and each have a special cosmetic gameplay effect.

You can purchase the pass at any point in your progression, retroactively unlocking any skins you have earned. This also applies to the Archnemesis Pass, which is still for sale in the store right now! For more information, visit pathofexile.com/vault', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(204, 14, '18', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Panel17', 'Art/2DArt/UIImages/Login/LeagueInfo/Sentinel/Heading17', '[]', 'We''re launching two new sets of Supporter Packs to celebrate the release of the Sentinel League: the Arcanist and Reaper packs. There are three price points available for each and they feature masses of points and several exclusive microtransactions that visually interact with gameplay in new ways.

<italic>{Path of Exile: Sentinel} will launch on May 13th (PDT) for PC and Mac, and on May 18th for Xbox and PlayStation.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 1, 0, '[]', '', '', '[]', '', 0, 0),
(205, 15, 'Trailer', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/KalandraThumbnailTrailer', '', '[]', '', 0, 'http://web.poecdn.com/public/videos/KalandraTrailer_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(206, 15, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Heading1', '[]', 'You may recognise Kalandra from the infamous Mirror of Kalandra, Path of Exile''s most valuable item. The Lake of Kalandra expansion explores the identity of this iconic character and allows you a taste of her power.

Our August expansion contains the Kalandra challenge league, improvements to the Atlas endgame, four new gems, 14 new unique items, 100+ buffed existing uniques, revamps to Harvest, Beyond and Archnemesis, a variety of balance changes and much more!', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(207, 15, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Heading2', '[]', 'In the Kalandra Challenge League, you''ll travel to the mirrored lake that granted Kalandra her powers of duplication. The lake manifests reflections of Wraeclast itself, which emerge from its misty surface as you approach. Fight through these dangerous encounters to uncover Kalandra''s mysteries and earn true power.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(208, 15, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Heading3', '["Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/screenshots/Panel3/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/screenshots/Panel3/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/screenshots/Panel3/Screenshot3"]', 'As you travel throughout Wraeclast, you''ll occasionally discover a Mirrored Tablet. Build up this Tablet by placing reflections of dangerous encounters at specific locations. Be careful though, some of these reflections contain immense challenges.

Once you have assigned a reflection to every empty location on your Tablet, you may open a portal to the Lake of Kalandra, which will manifest your creation for you to experience.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(209, 15, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Heading4', '["Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/screenshots/Panel4/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/screenshots/Panel4/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/screenshots/Panel4/Screenshot3"]', 'The farther away from the Lake''s entrance an encounter is, the greater its difficulty and rewards are. You''ll occasionally be offered choices to customise your Mirrored Tablet by swapping the layout around, perfecting your set of encounters and their rewards.

As you progress through the league, you''ll unlock special abilities to skip, reroll and exile choices you are offered, letting you refine your Tablets more efficiently. In the endgame, you''ll also be able to itemise your completed Tablets to save them for later or trade them away.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Kalandra/MirroredTablet.itemblob"]', '', '', '[]', '', 0, 0),
(210, 15, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Heading5', '[]', 'Alongside rewards from each encounter, the Lake can manifest new ways to create rare items. The Reflecting Mist will create a pair of rings or amulets, exact reflections of one other. On one item, half the properties are magnified in intensity, with the other half negated to hinder you. The other item has the opposite set of mods negated. You may only pick one of these reflections to take with you.

In the league''s late endgame, you may bring your own rings and amulets to the Mist. It will magnify, distort and reflect them in a similar way, providing access to previously-unattainable power on rare items.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Kalandra/SolHeart1.itemblob","Metadata/LeagueInfoPanelItems/Kalandra/SolHeart2.itemblob","Metadata/LeagueInfoPanelItems/Kalandra/OblivionBand1.itemblob","Metadata/LeagueInfoPanelItems/Kalandra/OblivionBand2.itemblob","Metadata/LeagueInfoPanelItems/Kalandra/DoomFinger1.itemblob","Metadata/LeagueInfoPanelItems/Kalandra/DoomFinger2.itemblob"]', '', '', '[]', '', 0, 0),
(211, 15, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Heading6', '[]', 'Atlas Memories offer a way to explore endgame content and earn very valuable rewards without having to specialise your Atlas Tree for it. In high-level maps, you''ll very rarely find a Memory item, which represents a set of memories that Alva, Niko, Einhar or Kirac has. They will provide a sequence of maps for you to explore as you relive the events of their past. These highly challenging and rewarding Memories can either be applied to your Atlas or traded to other players.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Kalandra/KiracsMemoryofPhaaryl.itemblob","Metadata/LeagueInfoPanelItems/Kalandra/NikosMemoryofDemonicOnslaught.itemblob"]', '', '', '[]', '', 0, 0),
(212, 15, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Heading7', '[]', 'This expansion introduces three new skill gems and one new support gem. Three of these are themed around lightning damage and shock.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Kalandra/AlchemistsMark.itemblob","Metadata/LeagueInfoPanelItems/Kalandra/GalvanicField.itemblob","Metadata/LeagueInfoPanelItems/Kalandra/LightningConduit.itemblob","Metadata/LeagueInfoPanelItems/Kalandra/OverchargeSupport.itemblob"]', '', '', '[]', '', 0, 0),
(213, 15, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Heading8', '[]', 'In this expansion, we''ve added 14 new unique items including a league-exclusive ring, a new pinnacle boss reward, a supporter unique, six new Grand Spectrum jewels and even some levelling uniques. We''ve also improved over 100 unique items, including both levelling uniques and endgame ones. Finding a unique item is now more likely to be an exciting moment, especially during the campaign.

We''re introducing another unique map, The Tower of Ordeals. In this map, you may challenge the Trialmaster and potentially earn unique items from the Ultimatum league. You can create this map by completing endgame Vaal content.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Kalandra/SoulAscension.itemblob","Metadata/LeagueInfoPanelItems/Kalandra/Ghostwrithe.itemblob","Metadata/LeagueInfoPanelItems/Kalandra/NyctasLantern.itemblob","Metadata/LeagueInfoPanelItems/Kalandra/MalachaisSimula.itemblob","Metadata/LeagueInfoPanelItems/Kalandra/ThousandRibbons.itemblob","Metadata/LeagueInfoPanelItems/Kalandra/HandsoftheHighTemplar.itemblob","Metadata/LeagueInfoPanelItems/Kalandra/TheTowerofOrdeals.itemblob"]', '', '', '[]', '', 0, 0),
(214, 15, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Heading9', '[]', 'We''ve overhauled rare and magic monsters throughout Path of Exile, revisited the difficulty and rewards of Archnemesis mods, revamped Beyond and have made large changes to Harvest.

Past league content now spawns a more consistent and less overwhelming quantity of rare monsters. Defeating monsters with multiple Archnemesis mods is now far more rewarding. Powerful monster mods now convert your item drops in a way that stacks with rewards from other mods and player item rarity or quantity bonuses. The Beyond league has been updated with the monsters and bosses from Scourge, and has been given a balance revamp. Harvest crafting has been overhauled to use a tradeable currency, and can now be done in your own time, at the horticrafting station in your hideout.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(215, 15, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Heading10', '["Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/screenshots/Panel10/Screenshot1"]', 'We''ve made many changes to Path of Exile''s balance, including an overhaul of the Trickster Ascendancy Class and Minion Itemisation. We''ve reworked the Trickster Ascendancy, with a focus on establishing thematically-appropriate defences and ways to manipulate speed. Check out its new Ascendancy skills in the screenshots on this panel.

With plenty of new itemisation opportunities, minion builds are now as rewarded for finding good items as other archetypes are. There are several new minion-focused base types that players can find and craft to improve the damage and survivability of their minions. Check out the patch notes for more information about these and other changes.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(216, 15, '12', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Heading11', '[]', 'In 2019, we hosted our first ever convention, ExileCon, to announce Path of Exile 2 and Path of Exile Mobile. Since then, we have been hard at work on both games. Now that we are getting close to release, we will finally be ready to announce the date the closed beta starts at ExileCon 2023. Tickets will go on sale in late August.

We''re holding ExileCon 2023 in Auckland, New Zealand, on the weekend of July 29-30, 2023. We''ll also be announcing everything there is to know about new game systems, character classes, items, and so on. Attendees will be able to play Path of Exile 2 and Path of Exile Mobile, see all the presentations live, meet our development team, hang out with their favourite streamers and much more. Keep an eye on the news for more information.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(217, 15, '13', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Panel12', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Heading12', '[]', 'Kirac''s Vault returns for the Kalandra League with a brand new set of exclusive unique item skins. Purchasing access to Kirac''s Vault allows you to claim these exclusive rewards as you complete map objectives in the Kalandra League. These exclusive skins apply to popular unique items that can be found in Path of Exile''s endgame and each has a special cosmetic gameplay effect.

You can purchase the pass at any point in your progression, retroactively unlocking any skins you have earned. This also applies to the Sentinel Pass, which is still for sale in the store right now! For more information, visit pathofexile.com/vault', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(218, 15, '14', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Panel13', 'Art/2DArt/UIImages/Login/LeagueInfo/Kalandra/Heading13', '[]', 'We''re launching two new sets of Supporter Packs to celebrate the release of Lake of Kalandra: the Knight and Rogue packs. There are three price points available for each and they feature masses of points and several exclusive microtransactions that visually interact with gameplay in new ways.

<italic>{Path of Exile: Lake of Kalandra} will launch on August 19th (PDT) for PC and Mac, and on August 24th for Xbox and PlayStation.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 1, 0, '[]', '', '', '[]', '', 0, 0),
(219, 16, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/SanctumThumbnailTrailer', '', '[]', '', 0, 'https://web.poecdn.com/public/videos/SanctumTrailer.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(220, 16, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Heading1', '[]', 'In Path of Exile: The Forbidden Sanctum, you will test your resolve as you make your way through the Sanctum''s dangerous halls. In the Sanctum, each decision you make can cost you greatly.

Our December expansion introduces the Sanctum challenge league and improvements to Path of Exile''s endgame, alongside two new Skill Gems, seven new Vaal Skill Gems, over 15 new Unique Items, significant balance changes to jewels, hexes, monster modifiers, unique weapons and more. We are also proud to introduce Ruthless, an optional new way to play Path of Exile with extreme item scarcity.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(221, 16, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Heading2', '[]', 'In this league, you''ll discover The Forbidden Sanctum, an ancient Templar enclave hidden beneath the Fellshrine Ruins. Abandoned for a long time, it is now controlled by a malevolent entity. You must explore it, uncover its secrets, and deal with the evil that lurks within.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(222, 16, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Heading3', '["Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/screenshots/Panel3/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/screenshots/Panel3/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/screenshots/Panel3/Screenshot3"]', 'Upon entering the Sanctum, you''ll uncover a map that reveals a few of the rooms ahead of you. Sparse details of the room and its rewards are shown, so you must plan carefully as each mistake will dwindle your resolve. When your resolve runs out, your Sanctum run ends. Each time you enter the Sanctum, you will seek to push yourself farther than before through its four floors.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(223, 16, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Heading4', '["Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/screenshots/Panel4/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/screenshots/Panel4/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/screenshots/Panel4/Screenshot3"]', 'The Sanctum''s rooms hold many secrets. Some contain ancient fountains you can rest at to restore a portion of your resolve. Others will curse you with an affliction, hindering your progress. These afflictions stack up as you explore deeper and deeper within the Sanctum. You can also receive boons, blessings that help you overcome the Sanctum''s dangers. Each time you enter the Sanctum, you will encounter a unique layout that you must assess and adapt to as you explore.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(224, 16, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Heading5', '["Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/screenshots/Panel5/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/screenshots/Panel5/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/screenshots/Panel5/Screenshot3"]', 'Inside the Sanctum, you will find gold coins called Aureus, a currency that the Templar used for commerce. It''s stored in treasure chests and falls from slain monsters. Although these coins belong to the Sanctum and will not leave with you, they can be traded with a merchant who you may encounter from time to time. Spend your Aureus wisely as it can be used to purchase a crucial boon when the time is right.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(225, 16, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Heading6', '["Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/screenshots/Panel6/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/screenshots/Panel6/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/screenshots/Panel6/Screenshot3"]', 'The sinister powers controlling the Sanctum will occasionally present you with an Accursed Pact. These pacts offer you a powerful benefit with a dangerous cost. Although the Pact will tempt you greatly, you must choose with care. The result of your choice could signal the end of your time in the Sanctum or be the turning point in your success.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(226, 16, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Heading7', '[]', 'Many rooms in the Sanctum will offer you a choice of currency items. You can take the reward now or leave it behind, with the promise of an even larger reward later. Deferring your reward to the end of the current floor or even the end of the entire Sanctum escalates it with great risk. If you run out of resolve before reaching this goal, you lose everything you gambled. Do you believe in yourself enough to take the risk and potentially reap a massive reward? Or do you play it safe and leave with what you have?', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(227, 16, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Heading8', '[]', 'As you explore the Sanctum, you''ll discover a special altar that Templar Relics can be placed on. These relics make you more powerful in the Sanctum and persist from run to run. Their continued power is the key to making it deeper into the Sanctum''s vaults each time you enter. As you accumulate more relics, you''ll need to make decisions around which ones most benefit you and arrange the Altar accordingly.

You may also uncover Sanctified Relics, a very rare type that directly affects your character''s build. You may use only one of these, but its benefits stay with you beyond the Sanctum walls and bestow the Templars'' power on you as you journey through Wraeclast.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Sanctum/PapyrusRelicofDiscounting.itemblob","Metadata/LeagueInfoPanelItems/Sanctum/UpliftingCenserRelicoftheTrove.itemblob","Metadata/LeagueInfoPanelItems/Sanctum/AncestralSanctifiedRelicofDestruction.itemblob","Metadata/LeagueInfoPanelItems/Sanctum/EmpoweringSanctifiedRelicofExpansion.itemblob"]', '', '', '[]', '', 0, 0),
(228, 16, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Heading9', '[]', 'The Forbidden Sanctum is home to many bosses, including random miniboss encounters, bosses at the end of each floor and an ultimate showdown against the entity that controls the Sanctum. These fights yield valuable rewards including Relics, piles of Aureus coins, masses of experience, new Unique Items and more.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(229, 16, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Heading10', '[]', 'We''ve improved the Atlas Passive Tree so that players don''t need to respec between mapping and boss-killing and can invest even further into content that they enjoy. We''ve added two new Atlas Memories themed around Domination and Bestiary, which include nine new Beastcrafting recipes. We''ve also rebalanced Eldritch Altars and have made Maven-witnessed map bosses a source of Awakened Gems.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Sanctum/FracturingOrb.itemblob","Metadata/LeagueInfoPanelItems/Sanctum/KiracsMemoryofthePantheon.itemblob","Metadata/LeagueInfoPanelItems/Sanctum/EinharsMemoryofHarvestBeasts.itemblob"]', '', '', '[]', '', 0, 0),
(230, 16, '12', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Heading11', '["Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/screenshots/Panel11/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/screenshots/Panel11/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/screenshots/Panel11/Screenshot3"]', 'The Forbidden Sanctum expansion introduces two new skill gems and seven new Vaal gems. Volcanic Fissure is a new fiery Slam skill that strikes the ground to create a chasm that winds towards your target until it erupts with a burst of fiery projectiles that explode when striking the ground. Frozen Legion is a spell that creates a ring of icy statues that attack using your weapon damage. These statues perform a sweeping ice slash which can overlap.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Sanctum/FrozenLegion.itemblob","Metadata/LeagueInfoPanelItems/Sanctum/VolcanicFissure.itemblob","Metadata/LeagueInfoPanelItems/Sanctum/VaalFlickerStrike.itemblob","Metadata/LeagueInfoPanelItems/Sanctum/VaalCleave.itemblob"]', '', '', '[]', '', 0, 0),
(231, 16, '13', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Panel12', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Heading12', '[]', 'There are over 15 new unique items to be found from within the Forbidden Sanctum and throughout Wraeclast and the Atlas. We''ve also massively increased the power and rarity of ten existing endgame unique weapons to bring them in line with some of Path of Exile''s most iconic unique items.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Sanctum/EternalDamnation.itemblob","Metadata/LeagueInfoPanelItems/Sanctum/Progenesis.itemblob","Metadata/LeagueInfoPanelItems/Sanctum/SoulTaker.itemblob","Metadata/LeagueInfoPanelItems/Sanctum/Starforge.itemblob"]', '', '', '[]', '', 0, 0),
(232, 16, '14', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Panel13', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Heading13', '[]', 'The Archnemesis monster mod system has been replaced with a system that more closely resembles Path of Exile''s initial monster mods, but with modernised balance and effects. This system has been streamlined so that each modifier only does one specific thing and describes exactly what it does. While you''ll still encounter modifier combinations that get your heart racing, these will be rarer than before and easier to understand in the heat of combat. Changes to rare monster rewards mean that you don''t need to summon a magic find culling character to help you with specific monster mods anymore.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(233, 16, '15', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Panel14', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Heading14', '[]', 'This expansion includes a number of changes to Path of Exile''s mechanics. We have improved Jewels as a source of ailment mitigation and have replaced most existing unique Jewels with some powerful new ones. We''ve also rebalanced Hexes to make them stronger against endgame bosses and have reworked most curse mechanics and curse uniques as a result. Our recent balance manifestos and expansion patch notes cover these changes in more detail.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Sanctum/Witchbane.itemblob","Metadata/LeagueInfoPanelItems/Sanctum/ArmageddonDream.itemblob","Metadata/LeagueInfoPanelItems/Sanctum/MorbidLeer.itemblob"]', '', '', '[]', '', 0, 0),
(234, 16, '16', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Panel15', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Heading15', '[]', 'Ruthless is an optional new game mode which offers a more challenging way to play Path of Exile. Ruthless players can expect extreme item scarcity, limited crafting and many other changes such as support gems being drop-only. Ruthless is a mode about friction, tension and anticipation. It''s much more difficult, but overcoming that difficulty feels highly rewarding. In a world where your items are far below par, every item drop has the potential to be the breakthrough one you need.

You can access Ruthless during character creation by selecting it as an additional flag alongside Solo Self-Found and Hardcore. To find out more about what changes it features and the philosophy behind its development, visit pathofexile.com/ruthless.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(235, 16, '17', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Panel16', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Heading16', '[]', 'Kirac''s Vault returns for the Sanctum League with a brand new set of exclusive unique item skins. Purchasing access to Kirac''s Vault allows you to claim these exclusive rewards as you complete map objectives in the Sanctum League. These exclusive skins apply to popular unique items that can be found in Path of Exile''s endgame and each has a special cosmetic gameplay effect.

You can purchase the pass at any point in your progression, retroactively unlocking any skins you have earned. This also applies to the Kalandra Pass, which is still for sale in the store right now! For more information, visit pathofexile.com/vault', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(236, 16, '18', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Panel17', 'Art/2DArt/UIImages/Login/LeagueInfo/Sanctum/Heading17', '[]', 'We''re launching two new sets of Supporter Packs to celebrate the release of The Forbidden Sanctum: the Forge and Gemling packs. There are three price points available for each and they feature masses of points and several exclusive microtransactions that visually interact with gameplay in new ways.

Path of Exile: The Forbidden Sanctum will launch on December 9th (PST) for PC and Mac, and on December 14th for Xbox and PlayStation.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 1, 0, '[]', '', '', '[]', '', 0, 0),
(237, 17, 'Trailer', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/CrucibleThumbnailTrailer', '', '[]', '', 0, 'https://web.poecdn.com/public/videos/CrucibleTrailer_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(238, 17, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Heading1', '[]', 'In Path of Exile: Crucible, you''ll learn about the ancient titans who once shaped the primordial surface of Wraeclast. If you''re powerful enough, you will earn the ability to forge their power onto your weapons.

Our April expansion introduces the Crucible challenge league, nine new Vaal Skills, Atlas Gateways, over ten new Unique Items and improvements to Breach, Abyss, Passive Tree Masteries, the Saboteur, the Pathfinder, Ruthless and much more!', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(239, 17, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Heading2', '["Art/2DArt/UIImages/Login/LeagueInfo/Crucible/screenshots/Panel2/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Crucible/screenshots/Panel2/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Crucible/screenshots/Panel2/Screenshot3"]', 'Crucible Forges are scattered throughout Wraeclast. When you find one, select one of your weapons and channel the power of the ancient titans to spawn a challenging encounter. The longer you channel for, the more the molten monsters merge together to form more fearsome foes. You''re in control of the difficulty and reward of these encounters.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(240, 17, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Heading3', '[]', 'In an iconically Path of Exile way, your weapons can now be imbued with powerful Passive Skill Trees of their own. Encounters at Crucible Forges grant you experience that lets you uncover the tree on a weapon and gradually progress through its skills. You can only allocate one skill from each tier, so choose your path through each Crucible Passive Tree carefully. If you''re lucky, you''ll find certain skills that, when allocated, are worth valuable currency or unique items when sold to a vendor.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(241, 17, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Heading4', '["Art/2DArt/UIImages/Login/LeagueInfo/Crucible/screenshots/Panel4/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Crucible/screenshots/Panel4/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Crucible/screenshots/Panel4/Screenshot3"]', 'Crucible''s endgame takes place in The Forge of the Titans, a dangerous area harbouring an ancient power: the ability to melt a weapon down, merging its Crucible Passive Tree with that of another weapon. This process produces unpredictable results, incorporating elements of each tree as well as random upgrades, downgrades and changes. Through careful use of the Forge, it''s possible to craft some incredibly powerful skill trees on your weapons.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Crucible/TitanianMantle.itemblob"]', '', '', '[]', '', 0, 0),
(242, 17, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Heading5', '[]', 'Among other endgame improvements, Path of Exile: Crucible introduces Atlas Gateways - nodes on the Atlas Passive Tree that allow instant travel between two locations. There are three pairs of gateways, each allowing travel from the left side of the tree to the right side or vice versa. Each end of the gateway consumes one Atlas Skill Point to allocate, but using them makes it possible to easily engage with all the content that you want to play, regardless of which side of the tree it''s on.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(243, 17, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Heading6', '[]', 'We''re overhauling Breach in many ways. Regular Breachstones are now much higher level, replacing Charged, Pure and Enriched Breachstones entirely. Flawless Breachstones can now be upgraded to with Blessings, or earned from an Atlas Tree passive. Breach monster pacing and density have been improved so that the pressure and rewards are consistent throughout an encounter. We have also tweaked Breach Scarabs, the Betrayal Research Safehouse, Breachstones from Kirac Missions, the Breach Harvest Crafting Option, the Fragment Stash Tab, Divination Cards, Breach Unique Items, Atlas Passives and more.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Crucible/GildedBreachScarab.itemblob"]', '', '', '[]', '', 0, 0),
(244, 17, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Heading7', '[]', 'Abyssal Depths now always contain an Abyssal Lich. Abysses have a chance to spawn a Stygian Spire in place of their reward chest, which drops a Stygian Vise, jewels and other items. You''re now guaranteed to always get a four-hole Abyss alongside your Abyssal Depths, rather than just a single hole. We''ve also updated Abyss passives on the Atlas Tree, Abyssal Lich encounter balance, Abyss uniques and Abyss Scarabs.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Crucible/WingedAbyssScarab.itemblob"]', '', '', '[]', '', 0, 0),
(245, 17, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Heading8', '["Art/2DArt/UIImages/Login/LeagueInfo/Crucible/screenshots/Panel8/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Crucible/screenshots/Panel8/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Crucible/screenshots/Panel8/Screenshot3"]', 'The Crucible expansion provides a lot of new ways to build characters and improve your favourite ones. We have revamped approximately half of the Masteries on the passive tree with lots of new build-improving stats to pick from. We have also bolstered the tree itself with new clusters for Link Skills, Stun Mitigation and Marks, and have added a few new Masteries.

We have also overhauled the Saboteur and Pathfinder Ascendancy Classes. In addition to Traps and Mines, the Saboteur can now specialise in Triggered Skills and Cooldown Recovery, including the ability to slow down the cooldowns of enemy skills. The Pathfinder now has the ability to turn many of its skills into Concoction-like abilities that consume its flask charges for additional effects.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(246, 17, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Heading9', '["Art/2DArt/UIImages/Login/LeagueInfo/Crucible/screenshots/Panel9/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Crucible/screenshots/Panel9/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Crucible/screenshots/Panel9/Screenshot3"]', 'Path of Exile: Crucible introduces nine new Vaal skills, which augment a wide variety of different builds. We''ve added Vaal Absolution, Vaal Arctic Armour, Vaal Lightning Arrow, Vaal Reap, Vaal Animate Weapon, Vaal Domination, Vaal Ice Shot, Vaal Rejuvenation Totem and Vaal Firestorm.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Crucible/VaalAbsolution.itemblob","Metadata/LeagueInfoPanelItems/Crucible/VaalArcticArmour.itemblob","Metadata/LeagueInfoPanelItems/Crucible/VaalLightningArrow.itemblob","Metadata/LeagueInfoPanelItems/Crucible/VaalReap.itemblob"]', '', '', '[]', '', 0, 0),
(247, 17, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Heading10', '[]', 'Path of Exile: Crucible also introduces more than ten new unique items, including three that are exclusive to the Crucible Challenge League.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Crucible/TaintedPact.itemblob","Metadata/LeagueInfoPanelItems/Crucible/BloodPrice.itemblob","Metadata/LeagueInfoPanelItems/Crucible/Widowhail.itemblob"]', '', '', '[]', '', 0, 0),
(248, 17, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Heading11', '[]', 'The Crucible Challenge League also starts with a competitive boss kill event! The first player to kill the Uber Searing Exarch and Uber Eater of Worlds in Ruthless Hardcore Solo Self-found will get to work with our design team to add a new unique item to Path of Exile. They''ll also receive a transferable Ultra VIP ticket to ExileCon in July. Second and third place finishers will receive a transferable VIP ticket to ExileCon. If you''d like to enter the event, just create a character in Ruthless Hardcore Solo Self-found on launch day!', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(249, 17, '12', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Panel12', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Heading12', '[]', 'Ruthless is Path of Exile''s game mode designed around extreme item scarcity. It''s challenging because you''re constantly behind the item power curve. We have made small improvements to Ruthless in Path of Exile: Crucible. Firstly, Eternal Orbs are back in Ruthless! These are extremely powerful currency items that allow you to imprint an item and restore it if you''re unhappy with the result of crafting. We disabled these game-wide seven years ago because they were far too powerful when combined with all of the crafting options Path of Exile offered at the time. Ruthless does not have the base game''s crafting featureset, and so we are enabling Eternal Orbs to drop in Ruthless, albeit extremely rarely.

Ruthless now has its own set of challenges to complete. Like the ones in early Path of Exile, there are a total of eight, and they''re very difficult. We''ll post more information in the news about these challenges before release.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Crucible/EternalOrb.itemblob"]', '', '', '[]', '', 0, 0),
(250, 17, '13', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Panel13', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Heading13', '[]', 'Our next livestream will take place from the ExileCon 2023 main stage! Held from July 28-29 (PDT) in Auckland, New Zealand, the event will be fully streamed online for you to watch from home. We''ll be unveiling masses of information about Path of Exile 2 and Path of Exile Mobile before streaming the entire Path of Exile 3.22 reveal and then every developer talk, panel and event from the convention. The livestream starts at 10am New Zealand time on July 29 (3pm PDT, July 28). Don''t miss it!', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(251, 17, '14', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Panel14', 'Art/2DArt/UIImages/Login/LeagueInfo/Crucible/Heading14', '[]', 'We''re launching two new sets of Supporter Packs to celebrate the release of Crucible: the Lithomancer and Enchanter packs. There are three price points available for each and they feature masses of points and several exclusive microtransactions that visually interact with gameplay in new ways.

<italic>{Path of Exile: Crucible} will launch on April 7th (PDT) for PC and Mac, and on April 12th for Xbox and PlayStation.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 1, 0, '[]', '', '', '[]', '', 0, 0),
(252, 18, 'Trailer', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/AncestorsThumbnailTrailer', '', '[]', '', 0, 'https://web.poecdn.com/public/videos/AncestorTrailer_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(253, 18, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Heading1', '[]', 'In this expansion, you will visit the Karui afterlife and defeat ten tribes in a series of tournaments to earn valuable new rewards.

Our August expansion introduces the Trial of the Ancestors challenge league, 16 new Atlas keystones, reworks of the Guardian and Chieftain Ascendancy classes, 14 new support gems and the return of a fan-favourite past league, The Forbidden Sanctum.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(254, 18, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Heading2', '["Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/screenshots/Panel2/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/screenshots/Panel2/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/screenshots/Panel2/Screenshot3"]', 'The fallen chieftains of each Karui tribe participate in a tournament called the Trial of the Ancestors. You will journey to their Afterlife to compete against these tribes by assembling your own team of Karui warriors. You''ll battle their chieftains in the tournament to earn valuable rewards.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(255, 18, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Heading3', '[]', 'In this league, use tradeable silver coins to gain passage to the Karui Afterlife. You''ll start out with a basic team of three Karui warriors to enter the Trial of the Ancestors.

In each match, you can select which tribe to compete against, based on the reward offered. You can examine the battlefield configuration of the enemy team and strategically place your warriors to challenge theirs. Then you and your party will compete alongside your warriors to destroy the opposing team''s totems and win the match.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Ancestor/SilverCoin.itemblob"]', '', '', '[]', '', 0, 0),
(256, 18, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Heading4', '["Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/screenshots/Panel4/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/screenshots/Panel4/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/screenshots/Panel4/Screenshot3"]', 'When you compete in tournaments, you''ll accumulate favour with each of the tribes. This can be spent on recruiting warriors and purchasing field items and equipment to power up your team. Each tribe has their own specialities and you can mix and match warriors from different tribes to build a team that embodies your strategy.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(257, 18, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Heading5', '[]', 'You earn rewards for each match you win. In addition to a selection of regular items that may be offered, there are some exclusive new rewards that you can only get from the Trial of the Ancestors. Passive Tree Tattoos are one such reward. These are not applied to your skin but are instead engraved on your soul. Applying your tattoo will change what the attribute skills on your passive tree do.

If you win the entire tournament, Hinekora can also offer you a new type of item called an Omen. They can be stored in your inventory until a condition is met, at which point it is consumed and its effect occurs. You can only consume one Omen per combat area. She may also offer a lock of her hair, which allows you to foresee the result of an item crafting outcome.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Ancestor/TattoooftheNgamahuFirewalker.itemblob","Metadata/LeagueInfoPanelItems/Ancestor/LoyaltyTattooofUtula.itemblob","Metadata/LeagueInfoPanelItems/Ancestor/TattoooftheRamakoScout.itemblob","Metadata/LeagueInfoPanelItems/Ancestor/TattoooftheValakoStormConduit.itemblob","Metadata/LeagueInfoPanelItems/Ancestor/HonouredTattoooftheHatungo.itemblob","Metadata/LeagueInfoPanelItems/Ancestor/HonouredTattoooftheWiseMan.itemblob","Metadata/LeagueInfoPanelItems/Ancestor/OmenofReturn.itemblob","Metadata/LeagueInfoPanelItems/Ancestor/OmenofRefreshment.itemblob","Metadata/LeagueInfoPanelItems/Ancestor/OmenoftheSoulDevourer.itemblob","Metadata/LeagueInfoPanelItems/Ancestor/OmenofFortune.itemblob","Metadata/LeagueInfoPanelItems/Ancestor/HinekorasLock.itemblob"]', '', '', '[]', '', 0, 0),
(258, 18, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Heading6', '[]', 'Each of the ten Karui tribes guard an exclusive unique item that embodies the essence of their tribe. These valuable heirlooms can only be earned by defeating that tribe in the Trial of the Ancestors. Hinekora, the Goddess of Death, also has four powerful unique items that may be offered to winners of the tournament.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Ancestor/BoundFate.itemblob","Metadata/LeagueInfoPanelItems/Ancestor/ArohonguisTending.itemblob","Metadata/LeagueInfoPanelItems/Ancestor/KitavasHunger.itemblob"]', '', '', '[]', '', 0, 0),
(259, 18, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Heading7', '[]', 'After meeting Divinia in Act Ten, you''ll find Sanctum items while playing maps in the endgame. These tradeable items each represent a whole floor of the Sanctum. Upon successfully completing that Sanctum floor, the next floor is generated as a tradeable item, with all your Boons, Afflictions and Resolve states built-in.

We have rebalanced The Forbidden Sanctum to provide more variety in the mechanics and monsters you encounter. Most notably, your primary character defences are now able to protect your resolve. Relics have also been rebalanced and are now tradeable.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Ancestor/ForbiddenTome.itemblob","Metadata/LeagueInfoPanelItems/Ancestor/SanctumVaultsResearch.itemblob","Metadata/LeagueInfoPanelItems/Ancestor/RevitalisingProcessionalRelicofthePixie.itemblob","Metadata/LeagueInfoPanelItems/Ancestor/TheBrokenCenser.itemblob"]', '', '', '[]', '', 0, 0),
(260, 18, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Heading8', '["Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/screenshots/Panel8/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/screenshots/Panel8/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/screenshots/Panel8/Screenshot3"]', 'Trial of the Ancestors introduces 16 new keystone passives to unlock on the Atlas Passive Tree. These keystones allow you to double down on content that you want to play, and offer control of how you want to experience Path of Exile''s endgame. With the right keystones allocated, you can craft Vaal Side areas, become possessed by a Tormented Spirit, place a single gigantic explosive charge in Expedition, or play any Kirac mod regardless of what he offers you.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(261, 18, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Heading9', '[]', 'As part of this expansion''s metagame rebalance, we have introduced 14 new support gems. These gems have been designed to take existing categories of skills and provide entirely new ways to play them, for example making your Warcries deal damage, having your projectiles return to you, or causing your totems to launch fiery mortars at enemies that hit them.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Ancestor/ReturningProjectilesSupport.itemblob","Metadata/LeagueInfoPanelItems/Ancestor/FrigidBondSupport.itemblob"]', '', '', '[]', '', 0, 0),
(262, 18, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Heading10', '["Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/screenshots/Panel10/Screenshot1"]', 'The Guardian Ascendancy Class has been revamped to bring it more in line with the modern power level of other Ascendancy Classes. It still keeps its focus on synergistic party play but with many more exciting options.

Harmony of Purpose now powers up parties using Link skills. Time of Need now completely heals and cleanses you every four seconds. Radiant and Unwavering Crusade both fully embrace the "Holy Summoner" theme by giving you access to some exciting new types of minions that are exclusive to this ascendancy class.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(263, 18, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Heading11', '["Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/screenshots/Panel11/Screenshot1"]', 'We have completely redesigned the Chieftain Ascendancy Class. It offers all new passive skills, many of which focus on themes of fire and other elemental damage alongside specialising in Totems, Strikes and Slams.

Its new skills let you cause enemies to explode, turn off enemies'' fire resistance while you''re stationary, convert passive skills to apply to fire damage and have your fire resistance apply to your cold and lighting resistances, among many other abilities.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(264, 18, 'BossKillEvent', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Panel12', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Heading12', '[]', 'To celebrate the release of Trial of the Ancestors, we''ll be hosting a boss-kill event. To enter, you will need to create a Hardcore Solo Self-found character in the Ancestor league, and race to kill all seven uber pinnacle bosses on the same character. We''ll post more information about the event and its prizes in the news before release. Best of luck to everyone!', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(265, 18, 'SupporterPacks', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Panel13', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/Heading13', '[]', 'We''re launching two new sets of Supporter Packs to celebrate the release of Trial of the Ancestors: the Shade and Disciple packs. There are three price points available for each and they feature masses of points and several exclusive microtransactions that visually interact with gameplay in new ways.

Path of Exile: Trial of the Ancestors will launch on August 18th (PDT) for PC and Mac, and on August 23rd for Xbox and PlayStation.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 1, 0, '[]', 'Art/2DArt/UIImages/Login/LeagueInfo/Ancestors/buylarge', '', '[]', '', 0, 0),
(266, 19, 'Trailer', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/AncestorsThumbnailTrailer', '', '[]', '', 0, 'https://web.poecdn.com/public/videos/AfflictionTrailer_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(267, 19, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Heading1', '[]', 'In Path of Exile: Affliction, you''ll cleanse the Viridian Wildwood of its Affliction, earn valuable rewards and learn the ancient ways of the Azmeri Wanderers.

Our December expansion introduces the Affliction challenge league, three new Wildwood Ascendancy Classes, the return of the Ultimatum League, over a hundred new Transfigured Gems, and much more!', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(268, 19, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Heading2', '[]', 'In the Affliction League, you will encounter Sacred Wisps that beckon you to enter overgrown passageways that lead to the Viridian Wildwood. A vile Affliction has covered this forest with a foreboding darkness. You''ll need to uncover the forest''s mysteries to put a stop to the source of the Affliction.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(269, 19, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Heading3', '["Art/2DArt/UIImages/Login/LeagueInfo/Affliction/screenshots/Panel3/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Affliction/screenshots/Panel3/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Affliction/screenshots/Panel3/Screenshot3"]', 'As you approach the darkness, your Wisps burn away the affliction that shrouds the forest. Make sure you tread carefully, because your Wisps only have a limited amount of power before they run out and you are returned to Wraeclast. Be warned, the darkness is full of cursed monsters that emerge to kill you.

As you explore, you might see other types of Wisps trapped inside the darkness. Follow the trails of Wisps by collecting them, and you may uncover many different secrets such as new characters, shrines, boss battles, and new encounters. There are many rewards to earn, for those brave enough to seek them.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(270, 19, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Heading4', '[]', 'As you return from the Wildwood, any Wisps you have saved from the Affliction disperse into the environment and inhabit randomly-chosen monsters, increasing their power and also their rewards. The different types of Wisps have different effects, and sometimes more than one type will inhabit a single monster, making the fight even harder and even more rewarding.

Primal Wisps grant an item rarity bonus to inhabited monsters, Wild Wisps grant an item quantity bonus, and Vivid Wisps cause them to drop currency items. If a monster gets all three types, they''ll drop more items of a higher rarity and a lot of currency.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(271, 19, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Heading5', '[]', 'While exploring the Wildwood, you might find some of the last few Azmeri Wanderers who have managed to survive in the forest since it was cursed.

Choose which of the Azmeri Wanderers that you will complete quests for to unlock one of three new Ascendancy classes which you can have in addition to your regular Ascendancy class. Up to eight points for these classes are unlocked as you complete quests for the Azmeri.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(272, 19, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Heading6', '["Art/2DArt/UIImages/Login/LeagueInfo/Affliction/screenshots/Panel6/Ascendancy1"]', 'The Warden of Eaves can teach you to become a Warden of the Maji, a powerful class that takes advantage of wilderness knowledge. Wardens of the Maji can coat their weapons with Tinctures, granting them special bonuses. For example, the Ironwood Tincture always stuns enemies on full life and the Oakbranch Tincture is a great finisher for bosses.

A Warden of the Maji has many other wilderness abilities such as Barkskin, which causes Bark to grow all over your body, increasing armour. As you take damage, the Bark temporarily falls off, increasing your evasion.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Affliction/DroopingIronwoodTinctureofPoaching.itemblob","Metadata/LeagueInfoPanelItems/Affliction/SubduingOakbranchTinctureoftheChase.itemblob"]', '', '', '[]', '', 0, 0),
(273, 19, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Heading7', '["Art/2DArt/UIImages/Login/LeagueInfo/Affliction/screenshots/Panel7/Ascendancy1"]', 'The Breaker of Oaths can teach you to become a Warlock of the Mists, a class specialising in the darker arts of the Azmeri. One powerful ability you can choose is Blood Hunt, which lets you consume corpses to gain more damage and protection against monsters that share a creature type with the corpse. The Breaker of Oaths can sell you additional corpses of exotic types, and these can also be used as powerful spectres. The Warlock of the Mists also gets access to many other abilities including a trio of new curse skills.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Affliction/ImperfectFieryCannibal.itemblob","Metadata/LeagueInfoPanelItems/Affliction/ImperfectFrozenCannibal.itemblob","Metadata/LeagueInfoPanelItems/Affliction/ImperfectDarkMarionette.itemblob","Metadata/LeagueInfoPanelItems/Affliction/PerfectHydra.itemblob"]', '', '', '[]', '', 0, 0),
(274, 19, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Heading8', '["Art/2DArt/UIImages/Login/LeagueInfo/Affliction/screenshots/Panel8/Ascendancy1"]', 'The Primal Huntress can teach you to become a Wildwood Primalist. Unlike the other new ascendancy classes, the Primal Huntress lets you customise your tree using Charms that have randomly generated skills from the regular ascendancy classes. Charms are attribute-aligned magic items that can have up to two random modifiers on them.

Wildwood Primalists get access to other powerful abilities, such as a small extra backpack, or the ability to use warcries to cause corpses to drop extra items.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Affliction/JuggernautsUrsineCharmoftheChampion.itemblob","Metadata/LeagueInfoPanelItems/Affliction/RaidersLupineCharmoftheSaboteur.itemblob","Metadata/LeagueInfoPanelItems/Affliction/OccultistsCorvineCharmoftheInquisitor.itemblob"]', '', '', '[]', '', 0, 0),
(275, 19, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Heading9', '[]', 'The Affliction Challenge League has many different types of rewards. Monsters you fight throughout Wraeclast can be affected by the Wisps you have brought back from the Viridian Wildwood, dramatically increasing the quality and quantity of items they drop. As you progress through the league, you will earn a Wildwood Ascendancy Class and the Charms, Corpses or Tinctures that it utilises. The Mists hide many additional secret rewards that you will discover as you explore. Path of Exile: Affliction also contains over 15 new unique items.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Affliction/Pragmatism.itemblob","Metadata/LeagueInfoPanelItems/Affliction/TheTrickstersSmile.itemblob","Metadata/LeagueInfoPanelItems/Affliction/TheUntouchedSoul.itemblob"]', '', '', '[]', '', 0, 0),
(276, 19, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Heading10', '[]', 'Ultimatum is finally going core. The Trialmaster has returned and will offer you a choice to undertake a deadly Vaal trial in exchange for great rewards. If you defeat the trial, he offers to go double or nothing with you. Do you take the risk and go for an even better reward? Or do you lock in the winnings you have already earned? We''ve done a full rebalance of Ultimatum and have added many new modifiers, Atlas passive skills, Keystones and rewards including both new and reworked Uniques.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Affliction/TaintedCatalyst.itemblob","Metadata/LeagueInfoPanelItems/Affliction/InscribedUltimatum.itemblob"]', '', '', '[]', '', 0, 0),
(277, 19, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Heading11', '[]', 'Alternate Quality Gems, Labyrinth Helmet Enchantments and Unique Threshold Jewels have been combined into a new system called Transfigured Gems - alternative versions of existing skill gems that have different functionality and balance. There are over a hundred of these, such as Frost Bomb of Instability, Detonate Dead of Scavenging, Raise Zombie of Falling, Firestorm of Meteors and many more.

The Divine Font at the end of the Eternal Labyrinth has been changed to a gem crafting device that can create Transfigured Gems, add quality or experience to gems, sacrifice a gem for one or more Treasure Keys, exchange Support Gems for Exceptional Support Gems like Empower or Enlighten, and more.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Affliction/FrozenLegionofRallying.itemblob","Metadata/LeagueInfoPanelItems/Affliction/VolcanicFissureofSnaking.itemblob","Metadata/LeagueInfoPanelItems/Affliction/BladestormofUncertainty.itemblob","Metadata/LeagueInfoPanelItems/Affliction/RaiseZombieofFalling.itemblob","Metadata/LeagueInfoPanelItems/Affliction/FlameDashofReturn.itemblob","Metadata/LeagueInfoPanelItems/Affliction/FirestormofPelting.itemblob","Metadata/LeagueInfoPanelItems/Affliction/FirestormofMeteors.itemblob","Metadata/LeagueInfoPanelItems/Affliction/BlightofContagion.itemblob","Metadata/LeagueInfoPanelItems/Affliction/FrostBombofInstability.itemblob","Metadata/LeagueInfoPanelItems/Affliction/DetonateDeadofScavenging.itemblob","Metadata/LeagueInfoPanelItems/Affliction/BladeTrapofGreatswords.itemblob","Metadata/LeagueInfoPanelItems/Affliction/DoubleStrikeofImpaling.itemblob","Metadata/LeagueInfoPanelItems/Affliction/BarrageofVolleyFire.itemblob","Metadata/LeagueInfoPanelItems/Affliction/BlinkArrowofBombardingClones.itemblob","Metadata/LeagueInfoPanelItems/Affliction/BlinkArrowofPrismaticClones.itemblob","Metadata/LeagueInfoPanelItems/Affliction/AnimateWeaponofRangedArms.itemblob"]', '', '', '[]', '', 0, 0),
(278, 19, 'SupporterPacksCopy', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Panel12', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/Heading14', '[]', 'We''re releasing our annual Core Supporter Packs alongside the release of Path of Exile: Affliction. There are five packs available that each include their full value in points, exclusive armour sets and additional cosmetic microtransactions that visually interact with gameplay in new ways. The higher packs also include physical merchandise and a new opportunity to leave your mark on Path of Exile.

Path of Exile: Affliction will launch on December 8 (PST) for PC and Mac, and on December 13 for Xbox and PlayStation.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 1, 0, '[]', 'Art/2DArt/UIImages/Login/LeagueInfo/Affliction/buylarge', '', '[]', '', 0, 0),
(279, 20, 'Trailer', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/NecropolisThumbnailTrailer', '', '[]', '', 0, 'https://web.poecdn.com/public/videos/NecropolisTrailer_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(280, 20, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Heading1', '[]', 'In Path of Exile: Necropolis, help Undertaker Arimor lay the spirits of the Eternal Empire to rest and experiment with their souls to create powerful items.' || char(13) || '
' || char(13) || '
Our March expansion introduces the Necropolis Challenge League, a plethora of changes to the endgame, new tier 17 Maps and Bosses and new Transfigured Gems.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(281, 20, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Heading2', '[]', 'In the Necropolis League, the wrathful spirits have begun to haunt the monsters of Wraeclast, unleashing their ancient fury and sorrow onto the world. The Undertaker provides you with the Lantern of Arimor, a powerful family heirloom which illuminates the spirits haunting monsters throughout Wraeclast. With it, the Undertaker hopes to employ you to rid Wraeclast of this menace - and further his cryptic cause.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(282, 20, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Heading3', '["Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/screenshots/Panel3/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/screenshots/Panel3/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/screenshots/Panel3/Screenshot3"]', 'Examine the Spirits haunting Wraeclast by peering through the Lantern of Arimor. The Lantern allows you to manipulate the Spirits, letting you configure which monsters they haunt. It would be wise to take your time with your decisions, for the Spirits are not forgiving.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(283, 20, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Heading4', '[]', 'The Undertaker''s mysterious soul experiments can coalesce into powerful items. Take the corpses of haunted monsters to the Necropolis, bury them in one of the many graves in the cemetery and exorcise them to forge items from their souls.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Necropolis/FilledCoffin.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/FilledCoffin1.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/FilledCoffin2.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/FilledCoffin3.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/FilledCoffin4.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/EmptyCoffin.itemblob"]', '', '', '[]', '', 0, 0),
(284, 20, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Heading5', '[]', 'Bury many Haunted monsters strategically to utilise a vast combination of different crafting modifiers, then exorcise them to achieve your perfect item. Exorcise corpses haunted by the family members of famous Eternal Empire bloodlines to create new Unique Items.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Necropolis/SpiritSalvation.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/VengeanceVeil.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/ArmageddonMitts.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/CorruptionMarch.itemblob"]', '', '', '[]', '', 0, 0),
(285, 20, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Heading6', '[]', 'Defeating Haunted monsters causes you to find areas with monsters that are blessed by Devoted Spirits. Devoted Spirits cause monsters to grant you with a wide variety of different rewards, such as dropping more and better items, spawning Shrines that grant buffs, and allowing you to find an NPC that gives you a Unique Item.' || char(13) || '
' || char(13) || '
The Necropolis expansion also introduces 14 new Unique Items, 5 of which are exclusive to the Necropolis League.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Necropolis/Wraithlord.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/Manastorm.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/TheTidesofTime.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/TheCelestialBrace.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/RavenousPassion.itemblob"]', '', '', '[]', '', 0, 0),
(286, 20, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Heading7', '[]', 'Find special monster packs trapped within Embers of the Allflame, a powerful relic of Wraeclast. Place these in the Lantern of Arimor to encounter abnormal monsters that yield special rewards.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Necropolis/AllflameEmberofFrogs.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/AllflameEmberofTawhoa.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/AllflameEmberofTul.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/AllflameEmberofTheVaalLegion.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/AllflameEmberofUntaintedBeasts.itemblob"]', '', '', '[]', '', 0, 0),
(287, 20, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Heading8', '[]', 'Path of Exile: Necropolis introduces a new tier of Endgame Difficulty which tests your characters in new ways - Tier 17 Maps. They feature a new set of bosses, more powerful monsters, and new rewards. Access the absolute pinnacle of Path of Exile''s most difficult bosses by completing these Maps and proving your worth.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Necropolis/GrimMire.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/BuriedZone.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/GodlessCage.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/DevouringFragment.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/AwakeningFragment.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/DecayingFragment.itemblob"]', '', '', '[]', '', 0, 0),
(288, 20, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Heading9', '[]', 'In this expansion, unlock access to multiple Atlas Passive Skill Trees which can be used to enhance your Endgame experience to its maximum potential. Earn up to two extra trees by progressing through the Atlas and choose your desired playstyle for each Endgame Map.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(289, 20, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Heading10', '[]', 'Scarabs which can be used to enhance your Endgame Maps have been overhauled. A myriad of new options have been added, giving ways to push the challenges and rewards of Endgame Maps to new heights.' || char(13) || '
' || char(13) || '
The Atlas Passive Skill Tree has also been improved to give increased access to content in more ways than ever before.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Necropolis/DeliriumScarab.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/UltimatumScarab.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/UltimatumScarabofBribing.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/UltimatumScarabofDueling.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/UltimatumScarabofCatalysing.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/UltimatumScarabofInscription.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/DivinationScarabofCuration.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/DivinationScarabofCompletion.itemblob"]', '', '', '[]', '', 0, 0),
(290, 20, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Heading11', '[]', 'Path of Exile: Necropolis includes new Skill and Support Gems and a range of new Transfigured Gems. Automate your Warcries and Instant Spells with the Call to Arms and Automation Skills, and empower your wand attacks with the Sacred Wisps Support. If you''ve been waiting for a transfigured version of your favourite skill, you''ll now be able to play exciting new variants of Poisonous Concoction, Tornado, Ice Shot, and more.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Necropolis/TornadoofElementalTurbulence.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/IceShotofPenetration.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/ArtilleryBallistaofFocusFire.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/CalltoArms.itemblob","Metadata/LeagueInfoPanelItems/Necropolis/Automation.itemblob"]', '', '', '[]', '', 0, 0),
(291, 20, 'SupporterPacks', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Panel12', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/Heading12', '[]', 'We''re launching two new sets of Supporter Packs to celebrate the release of Necropolis: the Solar and Eldritch packs. There are three price points available for each and they feature masses of points and several exclusive microtransactions that visually interact with gameplay in new ways.' || char(13) || '
' || char(13) || '
Path of Exile: Necropolis will launch on March 29th (PDT) for PC, Mac and Consoles.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 1, 0, '[]', 'Art/2DArt/UIImages/Login/LeagueInfo/Necropolis/buylarge', '', '[]', '', 0, 0),
(292, 21, 'Trailer', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/SettlersThumbnailTrailer', '', '[]', '', 0, 'https://web.poecdn.com/public/videos/SettlersTrailer_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(293, 21, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Panel1', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Heading1', '[]', 'In Path of Exile: Settlers of Kalguur, help Kalguuran pioneers to build the town of Kingsmarch and establish trade between Wraeclast and their homeland.' || char(13) || '
' || char(13) || '
Our July expansion introduces the Settlers of Kalguur challenge league, a new trade market system for currency, balance improvements including two Ascendancy Class changes, Endgame improvements, some further additions to the Campaign and some Quality of Life features.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(294, 21, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Panel2', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Heading2', '["Art/2DArt/UIImages/Login/LeagueInfo/Settlers/screenshots/Panel2/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Settlers/screenshots/Panel2/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Settlers/screenshots/Panel2/Screenshot3"]', 'In the Settlers of Kalguur Challenge League you will encounter some familiar faces from the Expedition league. Dannig, Rog, Tujen and Gwennen are seeking out resources in Wraeclast that can be used to begin town construction and establish a shipping trade route to Kalguur. They have recruited many characters from Wraeclast, including some you may recognise - but are also seeking the help of a powerful Exile, like yourself.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(295, 21, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Panel3', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Heading3', '["Art/2DArt/UIImages/Login/LeagueInfo/Settlers/screenshots/Panel3/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Settlers/screenshots/Panel3/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Settlers/screenshots/Panel3/Screenshot3"]', 'On your adventures you might find minerals such as Crimson Iron, which are veins of Iron that have been overrun with corruption, spawning dangerous foes when you approach. Or perhaps Orichalcum, which you will have to liberate from the demons worshipping it. Petrified Amber attracts mindless Blighted Enemies, while Bismuth has a strong affinity to the elements and causes the area to become unstable. If you''re lucky you might find Verisium, a material as valuable as it is dangerous, and guarded by very powerful foes.' || char(13) || '
' || char(13) || '
Each of these resources become available once you defeat the enemies guarding it. You''ll then be able to tag the deposit for mining. Now, who''s going to be doing the hard labour?', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(296, 21, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Panel4', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Heading4', '["Art/2DArt/UIImages/Login/LeagueInfo/Settlers/screenshots/Panel4/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Settlers/screenshots/Panel4/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Settlers/screenshots/Panel4/Screenshot3"]', 'Theopolis wasn''t built in a day, and neither will Kingsmarch, but many hands make light work. Head to the town and hire skilled workers who will aid you in mining, smelting, disenchanting, farming and other jobs needed in Kingsmarch. You''ll notice each person has their specialties, and a wage cost. It''ll be up to you to hire and fire as you please. Over the course of the league you''ll be searching for your perfect employees for each job. Once you have them, you''ll have to keep them paid, safe, and alive.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(297, 21, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Panel5', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Heading5', '["Art/2DArt/UIImages/Login/LeagueInfo/Settlers/screenshots/Panel5/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Settlers/screenshots/Panel5/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Settlers/screenshots/Panel5/Screenshot3"]', 'Eventually you can build a Harbour and establish a shipping route between a number of different Kalguuran and Karui ports for trade. Pile your acquired resources onto these ships and send them to a port of your choosing, where your traders will haggle for the best deals! Each Port will return specific rewards based on what you send them. When your shipment has returned you''ll get notified, and you can return to the town to collect your rewards at your leisure.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Settlers/YndasStand.itemblob","Metadata/LeagueInfoPanelItems/Settlers/TimeRune.itemblob","Metadata/LeagueInfoPanelItems/Settlers/PowerRune.itemblob","Metadata/LeagueInfoPanelItems/Settlers/TattoooftheValakoStormrider.itemblob","Metadata/LeagueInfoPanelItems/Settlers/TattoooftheTasalioWarrior.itemblob"]', '', '', '[]', '', 0, 0),
(298, 21, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Panel6', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Heading6', '["Art/2DArt/UIImages/Login/LeagueInfo/Settlers/screenshots/Panel6/Screenshot1"]', 'Aside from shipping, the Kalguurans are big on their technology. They have hired Isla, an engineer from the Heist League. Once at Endgame, Isla can help you build a series of Kalguuran-modified Map Devices which you can put a queue of Maps into. If you''ve hired a few skilled combatants, they will put themselves to work running those maps for you one after another.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(299, 21, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Panel7', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Heading7', '[]', 'Operated by Dannig himself, a Runesmithing Table is using powerful Kalguuran blacksmithing arts to engrave runic magic onto your weapons. There are many rune-types and combinations to choose from, and you can unlock new crafts that can be applied to your weapons as enchantments.' || char(13) || '
' || char(13) || '
The Kalguuran tech benefits don''t end there. We''re also bringing back a community-favourite recombination system. Isla is trying to master this, she just needs you to help her with getting resources. While recombination is not entirely the same as it used to be in the Sentinel league, it still allows you to combine two items together, hoping to get the best modifiers of each onto a single item.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Settlers/TerrorMaul.itemblob","Metadata/LeagueInfoPanelItems/Settlers/SiegeAxe.itemblob"]', '', '', '[]', '', 0, 0),
(300, 21, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Panel8', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Heading8', '["Art/2DArt/UIImages/Login/LeagueInfo/Settlers/screenshots/Panel8/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Settlers/screenshots/Panel8/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Settlers/screenshots/Panel8/Screenshot3"]', 'In this expansion we''re introducing a Currency Trade Market. The Kalguurans have recruited Faustus, another NPC from the Heist league who is proficient at Black Market trade and shady deals. He allows you to asynchronously buy and sell currency and most other stackable items with other players. All you need to do is select what currency you want, say what you have, and your ideal ratio. Faustus will make the trade happen for you, so long as there is someone selling on the other end for the same rate or less.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(301, 21, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Panel9', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Heading9', '[]', 'As your town grows, it will attract more attention, good and bad. Settlers of Kalguur features three endgame bosses that will close in on your operations, wanting a piece of the pie. They might capture and ransom your workers, even your entire ships. You''ll have to make some tough decisions - will you take them on, or pay them off?', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Settlers/Svalinn.itemblob"]', '', '', '[]', '', 0, 0),
(302, 21, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Panel10', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Heading10', '["Art/2DArt/UIImages/Login/LeagueInfo/Settlers/screenshots/Panel10/gladiator"]', 'The Gladiator Ascendancy Class has received its long-awaited rework. Like before there are passive skills that allow you to invest in Bleeding, and Block. We''ve also designed new Skills replacing some of the old ones, and added a new branch which allows you to invest into Retaliation Skills, which are a new type of skill that allows you to unleash devastating damage upon meeting certain conditions in combat.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Settlers/Eviscerate.itemblob","Metadata/LeagueInfoPanelItems/Settlers/Swordstorm.itemblob","Metadata/LeagueInfoPanelItems/Settlers/DivineRetribution.itemblob"]', '', '', '[]', '', 0, 0),
(303, 21, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Panel11', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Heading11', '["Art/2DArt/UIImages/Login/LeagueInfo/Settlers/screenshots/Panel11/warden"]', 'We''re introducing the Warden, a new Ascendancy class that replaces the Raider Ascendancy. This class is largely inspired by its predecessor from the Affliction league, with a few changes. The Warden focuses on Elemental Attacks, grants Barkskin which can be used to mitigate Physical Damage from Hits, and specialises in Tinctures which have been reworked and introduced into the game as a core item type you can find throughout Wraeclast.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Settlers/PrismaticTincture.itemblob","Metadata/LeagueInfoPanelItems/Settlers/RosethornTinctureofSkill.itemblob","Metadata/LeagueInfoPanelItems/Settlers/PotentPoisonberryTinctureofIre.itemblob"]', '', '', '[]', '', 0, 0),
(304, 21, '12', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Panel12', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Heading12', '[]', 'In Path of Exile: Settlers of Kalguur, we''ve done a lot of balance work including drastic alterations to Melee Skills, Block, Rage, Warcries, Banners, Bleed, Impale, added new Base Types to Endgame, buffed Modifiers on Endgame Items, buffed Critical Strike Chances on Weapons and much much more. Check out the full changes in the Path of Exile: Settlers of Kalguur Patch Notes.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Settlers/DemonsHorn.itemblob","Metadata/LeagueInfoPanelItems/Settlers/FecundRoyalPlate.itemblob","Metadata/LeagueInfoPanelItems/Settlers/VentorsGamble.itemblob"]', '', '', '[]', '', 0, 0),
(305, 21, '13', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Panel13', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Heading13', '[]', 'There are a myriad of changes coming to Endgame in Settlers of Kalguur. We''re changing many Scarabs, adding a 6th Map Device Slot, introducing exciting new encounters in Tier 16 and Tier 17 Maps, updating Blight and Ritual in Endgame and more. We''ve also added a set of new Chisel types and massively increased the drop rate of Valdo''s Puzzle Boxes.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Settlers/DivinationScarabofPilfering.itemblob","Metadata/LeagueInfoPanelItems/Settlers/TitanicScarabofLegend.itemblob","Metadata/LeagueInfoPanelItems/Settlers/MavensChiselofProliferation.itemblob","Metadata/LeagueInfoPanelItems/Settlers/MavensChiselofProcurement.itemblob","Metadata/LeagueInfoPanelItems/Settlers/AnAudienceWithTheKing.itemblob","Metadata/LeagueInfoPanelItems/Settlers/PrismaticOil.itemblob"]', '', '', '[]', '', 0, 0),
(306, 21, '14', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Panel14', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Heading14', '[]', 'We''ve been hard at work improving the Path of Exile experience on consoles. The game now takes full advantage of the console hardware: loading times have been reduced even further, pop-in has been reduced, and textures won''t start unloading in heavy scenes.' || char(13) || '
' || char(13) || '
Furthermore, overall visual fidelity has been improved for all new generation consoles. Path of Exile now uses the highest available resolution textures and water effects. We''ve installed a new upscaling algorithm that improves the crispness of dynamic resolution, with an additional anti-aliasing pass on top of that.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '', '[]', '', 0, 0),
(307, 21, 'SupporterPacks', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Panel15', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/Heading15', '[]', 'We''re launching two new sets of Supporter Packs to celebrate the release of Settlers of Kalguur: the Paladin and Penance packs. There are three price points available for each and they feature masses of points and several exclusive microtransactions that visually interact with gameplay in new ways.' || char(13) || '
' || char(13) || '
Path of Exile: Settlers of Kalguur will launch on July 26th (PDT) for PC, Mac and Consoles.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 1, 0, '[]', 'Art/2DArt/UIImages/Login/LeagueInfo/Settlers/buylarge', '', '[]', '', 0, 0),
(308, 22, 'Trailer', 'Art/2DArt/UIImages/Login/LeagueInfo/Secrets/SettlersThumbnailTrailer', '', '[]', '', 0, 'http://web.poecdn.com/public/videos/SecretsOfTheAtlasTrailer_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(309, 22, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Secrets/Panel1', '', '[]', 'In Path of Exile: Secrets of the Atlas, tears have begun to appear in the Atlas leading to different realities. The Originator of these realities has entangled themselves within the very fabric of the Atlas and they''re now trapped! Track down the source of the tears and uncover the secrets within.' || char(13) || '
' || char(13) || '
Our new expansion introduces an additive endgame storyline, a new type of endgame crafting mechanic, three new endgame bosses, a new challenge league, dozens of new unique items and much more.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Path of Exile: Secrets of the Atlas', '[152,174,210]', '', 0, 0),
(310, 22, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Secrets/Panel2', '', '[]', 'Meet Eagon, an intelligent man of mysterious heritage. He is trying to discover his origins, but in doing so, he has found more than he bargained for.' || char(13) || '
' || char(13) || '
In his investigation, Eagon has encountered distortions of reality. Occasionally he catches a glimpse of a young girl through the rifts - Zana. He knows her as the daughter of the great inventor who shaped the Atlas as we know it. These tears in reality, he has discovered, are actually threads of memory, distorted and made real by the Atlas.' || char(13) || '
' || char(13) || '
Eagon is adamant to discover what is causing this and save Zana.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'A New Endgame Storyline', '[152,174,210]', '', 0, 0),
(311, 22, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Secrets/Panel3', '', '["Art/2DArt/UIImages/Login/LeagueInfo/Secrets/screenshots/Panel3/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Secrets/screenshots/Panel3/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Secrets/screenshots/Panel3/Screenshot3"]', 'In the Atlas you will encounter Threads of Consciousness, a strange thread-like substance that appears near the tears. By using a powerful gauntlet of his own making, Eagon is able to create a link to these memory threads and open portals to them. Working with Eagon, you must step through and find Zana, or whatever remains of her.' || char(13) || '
' || char(13) || '
The areas opened by Eagon can be fully influenced by your Atlas Tree, Scarabs and Fragments. Your goal is to reach the end, the source of this Stream of Consciousness by fighting through a number of Maps.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Step into the Memories', '[152,174,210]', '', 0, 0),
(312, 22, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Secrets/Panel4', '', '["Art/2DArt/UIImages/Login/LeagueInfo/Secrets/screenshots/Panel4/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Secrets/screenshots/Panel4/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Secrets/screenshots/Panel4/Screenshot3"]', 'The areas you are asked to investigate are not just regular Maps, they''re influenced by the Memories of Zana herself and have manifested dangerous threats.' || char(13) || '
' || char(13) || '
This influence takes the form of having monsters imbued with Memory Petals. Defeating these enemies causes the power of those monsters to transfer onto you.' || char(13) || '
' || char(13) || '
Each of the Memories within the Threads will grant you a different special ability. The enemy power you received fuels this ability and allows you to use it. As you progress further into the Thread of Memories, the Maps can have more than one Memory and thus you can have more than one powerful ability.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Harness New Powers', '[152,174,210]', 'Art/Videos/LeagueInfo/Secrets/Panel4.bk2', 0, 0),
(313, 22, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Secrets/Panel5', '', '["Art/2DArt/UIImages/Login/LeagueInfo/Secrets/screenshots/Panel5/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Secrets/screenshots/Panel5/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Secrets/screenshots/Panel5/Screenshot3"]', 'The final map in each Thread is a true challenge, filled with new monsters and guarded by a powerful boss. Each of these bosses are familiar but dreamlike, drawn from Zana''s memories and warped by the Atlas into something very different and terrifying.' || char(13) || '
' || char(13) || '
If you manage to defeat one of these warped memory bosses, Eagon will be able to harness its power to delve deeper into the memory rifts. In those depths you will encounter the most significant of Zana''s memories which manifested into three new Pinnacle bosses.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Face New Pinnacle Bosses', '[152,174,210]', '', 0, 0),
(314, 22, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Secrets/Panel6', '', '[]', 'Defeating the Pinnacle bosses will grant you new powerful uniques and Memory Influenced Maps which introduce Memory Strands, a new item mechanic. The new Pinnacle bosses also drop new Crafting Currencies which can be used to manipulate the Memory Strands on items. In addition, we have supported the new endgame content with a set of new passive skills on Atlas Passive Tree.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Secrets/ProsperosProtection.itemblob","Metadata/LeagueInfoPanelItems/Secrets/EnmitysEmbrace.itemblob","Metadata/LeagueInfoPanelItems/Secrets/OrbofRemembrance.itemblob","Metadata/LeagueInfoPanelItems/Secrets/OrbofUnravelling.itemblob","Metadata/LeagueInfoPanelItems/Secrets/OrbofIntention.itemblob","Metadata/LeagueInfoPanelItems/Secrets/AmbushHarness.itemblob","Metadata/LeagueInfoPanelItems/Secrets/WineoftheProphet.itemblob","Metadata/LeagueInfoPanelItems/Secrets/Starcaller.itemblob"]', '', 'Reap the Rewards', '[152,174,210]', '', 0, 0),
(315, 22, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Secrets/Panel7', '', '["Art/2DArt/UIImages/Login/LeagueInfo/Secrets/screenshots/Panel7/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Secrets/screenshots/Panel7/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Secrets/screenshots/Panel7/Screenshot3"]', 'In the Secrets of the Atlas expansion, we''re introducing the new challenge league, Mercenaries of Trarthus.' || char(13) || '
' || char(13) || '
In this league, you will meet lawless veterans who have travelled all the way from the brutal lands of Trarthus. They''re ready to offer their sinister services, but not for free.' || char(13) || '
' || char(13) || '
You will find these Mercenaries as you journey through Wraeclast, one in each area. They each have their own personalities, and come with different builds, skills, and items already equipped.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Meet the Mercenaries of Trarthus', '[152,174,210]', '', 0, 0),
(316, 22, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Secrets/Panel8', '', '[]', 'Upon meeting a Mercenary, as per Trarthan tradition, they will challenge you to a duel to test your strength.' || char(13) || '
' || char(13) || '
Before beginning the duel, you will be offered an overview of the Mercenary you''ve encountered. You can then decide to duel them, choosing a reward for your victory: you can hire their services, take one of their items, or exile them.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Respect Trarthan Tradition', '[152,174,210]', '', 0, 0),
(317, 22, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Secrets/Panel9', '', '["Art/2DArt/UIImages/Login/LeagueInfo/Secrets/screenshots/Panel9/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Secrets/screenshots/Panel9/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Secrets/screenshots/Panel9/Screenshot3"]', 'After hiring a Mercenary, you can view their items, basic stats, and the skills they have at any point. All of these are randomly generated for each Mercenary, guided by a range of class archetypes.' || char(13) || '
' || char(13) || '
Any of your Mercenaries you have active or in your reserves can have their equipment replaced with items of your choosing. Their level doesn''t change after being hired so you are constantly going to be looking out for more skilled and more powerful Mercenaries as you advance through the campaign and Endgame.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Find a Perfect Companion', '[152,174,210]', '', 0, 0),
(318, 22, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Secrets/Panel10', '', '[]', 'You may also find particular Trarthan Mercenaries throughout Wraeclast bearing the name of their house. These are noble Mercenaries that descend from the four major death trade families in Trarthus. Noble Mercenaries are less common, but their equipped items are far better - they are also the sole source of the new Infamous modifiers.' || char(13) || '
' || char(13) || '
Sometimes when you fight a Mercenary, you may notice the skills they''re using are different from normal. If you''re lucky you will be able to select that as your reward when challenging them. Then defeat them, and they''ll drop the Trarthan Gem as promised.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Secrets/Howlcrack.itemblob","Metadata/LeagueInfoPanelItems/Secrets/GolemTalons.itemblob","Metadata/LeagueInfoPanelItems/Secrets/RuneTether.itemblob","Metadata/LeagueInfoPanelItems/Secrets/StormCallofTrarthus.itemblob","Metadata/LeagueInfoPanelItems/Secrets/SpectralShieldThrowofTrarthus.itemblob"]', '', 'Infamous Trarthan Armaments', '[152,174,210]', '', 0, 0),
(319, 22, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Secrets/Panel11', '', '[]', 'The Mercenaries Challenge League comes with a fresh set of 40 optional challenges to complete. By doing so, you will earn the pieces of Watcher''s Wrath Armour Set. You''ll start earning these microtransactions from as early as four completed challenges.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Complete the Challenges', '[152,174,210]', '', 0, 0),
(320, 22, '12', 'Art/2DArt/UIImages/Login/LeagueInfo/Secrets/Panel12', '', '[]', 'Kingsmarch from the Settlers of Kalguur League is going core but there will be no more town building! Instead, you will be able to enjoy Kingsmarch''s services to their full effect right from the start.' || char(13) || '
' || char(13) || '
In addition, we have added Runegrafting, a new passive tree mechanic that can be used to replace a passive tree Mastery node. The Settlers mechanic has also received Atlas Passive Tree support and a handful of Scarabs.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Secrets/RunegraftoftheSoulwick.itemblob","Metadata/LeagueInfoPanelItems/Secrets/RunegraftofBlasphemy.itemblob","Metadata/LeagueInfoPanelItems/Secrets/RunegraftoftheNovamark.itemblob"]', '', 'Benefit from Kingsmarch''s Services', '[152,174,210]', '', 0, 0),
(321, 22, '13', 'Art/2DArt/UIImages/Login/LeagueInfo/Secrets/Panel13', '', '[]', 'In Secrets of the Atlas we are reworking the Betrayal mechanic.' || char(13) || '
' || char(13) || '
The Mastermind is now accessible through a new fragment that has a chance to drop from Safehouse Leaders and no longer resets the state of the Immortal Syndicate. The boss fight itself has also been improved, now with significantly fewer immunity phases and new rewards, including Allflame Embers.' || char(13) || '
' || char(13) || '
We have also introduced several Quality of Life improvements to Betrayal, rebalanced Safehouse rewards, added Veiled Chaos Orbs back to the Betrayal drop pool, improved Betrayal Atlas Tree nodes and the Scarabs that modify it.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Secrets/SyndicateMedallion.itemblob","Metadata/LeagueInfoPanelItems/Secrets/VeiledExaltedOrb.itemblob","Metadata/LeagueInfoPanelItems/Secrets/VeiledChaosOrb.itemblob","Metadata/LeagueInfoPanelItems/Secrets/AllflameEmberoftheEthereal.itemblob"]', '', 'Betrayal Rework', '[152,174,210]', '', 0, 0),
(322, 22, '14', 'Art/2DArt/UIImages/Login/LeagueInfo/Secrets/Panel14', '', '[]', 'In this expansion we have added a number of quality of life improvements our players have been asking for. For example, you will be able to unveil items by yourself at any time and use Orbs of Horizon on Elder-Guardian and Conqueror maps. We have also implemented the ability to pause the game, added a small additional inventory to the Map Device and introduced several other useful features.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Quality of Life Features', '[152,174,210]', '', 0, 0),
(323, 22, 'SupporterPacks', 'Art/2DArt/UIImages/Login/LeagueInfo/Secrets/Panel15', '', '[]', 'We''re launching two new sets of Supporter Packs to celebrate the release of Secrets of the Atlas: the Phrecian Magistrate and Cryptkeeper packs. There are three price points available for each and they feature masses of points and several exclusive microtransactions that visually interact with gameplay in new ways.' || char(13) || '
' || char(13) || '
Path of Exile: Secrets of the Atlas will launch on June 13 (PDT) for PC, Mac and Consoles.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 1, 0, '[]', 'Art/2DArt/UIImages/Login/LeagueInfo/Secrets/buylarge', 'Show Your Support', '[152,174,210]', '', 0, 0),
(324, 23, 'Trailer', 'Art/2DArt/UIImages/Login/LeagueInfo/Keepers/SettlersThumbnailTrailer', '', '[]', '', 0, 'http://web.poecdn.com/public/videos/KeepersOfTheFlameTrailer_En.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(325, 23, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Keepers/Panel1', '', '[]', 'In Path of Exile: Keepers of the Flame you will continue the story of Breach, an iconic league from Path of Exile''s past, and assist a mysterious monastic order in defending Wraeclast from the Breachlords.' || char(13) || '
' || char(13) || '
Our October expansion introduces new, twisted ways to empower your character, alongside new crafting mechanics and gems, Bloodline Ascendancies, three new uber pinnacle bosses, a plethora of quality of life features, and the long-anticipated Asynchronous Trade system.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Path of Exile: Keepers of the Flame', '[174,130,204]', '', 0, 0),
(326, 23, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Keepers/Panel2', '', '[]', '<italic>{"They come from another world... a barren world... and they crave our living land and sky. Our Unbroken Sun. They cannot be allowed to gain a foothold here."' || char(13) || '
' || char(13) || '
- Ailith, First of the Keepers}' || char(13) || '
' || char(13) || '
The Breachlords are advancing further into the outer world, establishing their ominous constructs across Wraeclast. To stop their conquest, Ailith founded the Order of the Keepers of the Flame. Harness the power of the Flame from Ailith and destroy the Breach infestations once and for all.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'The Order of the Keepers', '[174,130,204]', '', 0, 0),
(327, 23, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Keepers/PanelFrame', '', '["Art/2DArt/UIImages/Login/LeagueInfo/Keepers/screenshots/Panel3/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Keepers/screenshots/Panel3/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Keepers/screenshots/Panel3/Screenshot3"]', 'The Keepers of the Flame introduces a new type of Breach encounter. In areas you will find Breach monsters creating strange shapes and structures that don''t belong in this world. Ailith can destroy these, but needs you to protect her as she empowers the Flame to do so. Hold off the assault long enough, and she''ll be able to blast it all away.' || char(13) || '
' || char(13) || '
In some of the areas, the gap between worlds is strained. A massive Breach Hand sunders the space between dimensions, and touching it will open an Unstable Breach causing monsters to flood in. Slaughter them quickly enough to stabilise the Breach.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'The Keepers Challenge League', '[174,130,204]', 'Art/Videos/LeagueInfo/Keepers/Panel3.bk2', 0, 0),
(328, 23, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Keepers/Panel4', '', '["Art/2DArt/UIImages/Login/LeagueInfo/Keepers/screenshots/Panel4/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Keepers/screenshots/Panel4/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Keepers/screenshots/Panel4/Screenshot3"]', 'As you work more with Ailith, she will bring you to the Monastery of the Keepers, the hallowed halls of her order. Here you will discover the growing heart of the Keepers'' power,' || char(13) || '
The Genesis Tree.' || char(13) || '
' || char(13) || '
Being an engine of unholy creation, the Genesis Tree can grow all sorts of twisted rewards like new Currency, Uniques, and a new special type of items, Grafts. The Genesis Tree also has a Passive Tree itself, which can be used to improve the rewards it will grow for you.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'The Genesis Tree', '[174,130,204]', '', 0, 0),
(329, 23, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Keepers/Panel5', '', '[]', 'Directly infused into your body, Grafts grant passive benefits and a wide selection of powerful skills, offering everything from damage to potent defensive buffs and crowd control. There are sixteen different Graft types you can grow, each with their own skill. Unlock a second Graft slot as your Genesis Tree grows, giving you even more customization for your build!', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Keepers/MottledUndeath.itemblob","Metadata/LeagueInfoPanelItems/Keepers/SoleTendon.itemblob"]', '', 'A Handy Upgrade', '[174,130,204]', '', 0, 0),
(330, 23, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Keepers/Panel6', '', '[]', 'The Genesis Tree can grow misshapen currency orbs that work only on your Grafts, giving them new interesting mods. Sometimes, growing currency can be more successful, producing Foulborn currencies which can result in some extremely powerful outcomes.' || char(13) || '
' || char(13) || '
The Unique Items you are growing on the Genesis Tree can also become Foulborn, mutating one of the existing modifiers on the item into a new one, which can result in some interesting new ways to use that Unique.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Keepers/UnstableImplant.itemblob","Metadata/LeagueInfoPanelItems/Keepers/FoulbornRegalOrb.itemblob","Metadata/LeagueInfoPanelItems/Keepers/FoulbornTheRedDream.itemblob","Metadata/LeagueInfoPanelItems/Keepers/FoulbornEshsVisage.itemblob"]', '', 'Foulborn Fortune', '[174,130,204]', '', 0, 0),
(331, 23, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Keepers/PanelFrame', '', '["Art/2DArt/UIImages/Login/LeagueInfo/Keepers/screenshots/Panel7/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Keepers/screenshots/Panel7/Screenshot2"]', 'In Endgame areas you might run into Breach constructions that have been left without opposition for too long and have grown into Breach Hives. These are the visions of the Breachlords made real in Wraeclast, teeming constructions full of Breach Monsters that you must raid and destroy with the help of Ailith.' || char(13) || '
' || char(13) || '
You may even encounter some of the Breachlords themselves, who will not be happy to have you intruding on their planned conquest.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Destroy the Hives', '[174,130,204]', 'Art/Videos/LeagueInfo/Keepers/Panel7.bk2', 0, 0),
(332, 23, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Keepers/PanelFrame', '', '[]', 'In Keeper of the Flames, we are adding a collection of new Skill and Support gems, giving you access to potent Kineticism, screen-clearing whirlwinds, fiery bombardments from above,' || char(13) || '
and much more.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Keepers/Conflagration.itemblob","Metadata/LeagueInfoPanelItems/Keepers/WindburstSupport.itemblob","Metadata/LeagueInfoPanelItems/Keepers/KineticRain.itemblob"]', '', 'New Skill and Support Gems', '[174,130,204]', 'Art/Videos/LeagueInfo/Keepers/Panel8.bk2', 0, 0),
(333, 23, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Keepers/PanelAscendancy', '', '["Art/2DArt/UIImages/Login/LeagueInfo/Keepers/screenshots/Panel9/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Keepers/screenshots/Panel9/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Keepers/screenshots/Panel9/Screenshot3"]', 'In this expansion, you will be able to absorb the abilities of the certain bosses you defeat, in the form of additional 10 Bloodline Ascendancy Classes.' || char(13) || '
' || char(13) || '
Bloodline Classes are a new means of further character customisation, secondary Ascendancy classes that are unlocked by defeating bosses all over Path of Exile''s endgame. Bloodline Ascendancies can be taken on any class. There are countless possible combinations with this system, we are excited to see what crazy and interesting builds you come up with!', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', '10 Bloodline Ascendancy Classes', '[174,130,204]', '', 0, 0),
(334, 23, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Keepers/Panel10', '', '[]', 'Manifested from the memories of Zana, the Incarnation encounters festered into' || char(13) || '
something truly deadly!' || char(13) || '
' || char(13) || '
In Keepers of the Flame, we are introducing three new Uber Incarnation boss fights, offering an imposing challenge alongside powerful rewards.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Keepers/TheUnseenHue.itemblob","Metadata/LeagueInfoPanelItems/Keepers/FesteringResentment.itemblob"]', '', 'Uber Incarnations', '[174,130,204]', '', 0, 0),
(335, 23, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Keepers/Panel11', '', '[]', 'Now that the Asynchronous Trade has been a fantastic success in Path of Exile 2, we are excited to add it in Path of Exile: Keepers of the Flame!' || char(13) || '
' || char(13) || '
Starting from Act 6, Faustus will be managing your trade requests, including the Currency Exchange. Just place your items into the new Merchant''s Tabs, for direct and instant purchase by other players even when you''re not online. Happy trading!', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Introducing Asynchronous Trade', '[174,130,204]', '', 0, 0),
(336, 23, '12', 'Art/2DArt/UIImages/Login/LeagueInfo/Keepers/Panel12', '', '[]', 'We are adding more than a dozen Quality of Life features based on requests from our community. The Heist Rogues will now automatically begin at maximum level and your Atlas Passive Tree, as well as the regular Passive Skill Tree, will now be instantly refundable with Gold. Level up all of your gems with one click and you can now identify all items in your inventory at once,' || char(13) || '
with no Scrolls of Wisdom!', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Quality of Life Features', '[174,130,204]', '', 0, 0),
(337, 23, '13', 'Art/2DArt/UIImages/Login/LeagueInfo/Keepers/Panel13', '', '[]', 'The Keepers Challenge League introduces 40 new optional challenges to pursue, and completing them will award you with the Keeper of the Flame Armour Set, allowing you to truly embrace becoming a monk and worshipping the Dreamer. You''ll start earning these microtransactions from twelve completed challenges.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Complete the Challenges', '[174,130,204]', '', 0, 0),
(338, 23, 'SupporterParks', 'Art/2DArt/UIImages/Login/LeagueInfo/Keepers/Panel14', '', '[]', 'To celebrate the launch of the Keepers of the Flame, we''re launching two new sets of Supporter Packs: the Champion of Theopolis and Verdant Magus packs. There are three price points available for each and they feature masses of points and several exclusive microtransactions that visually interact with gameplay in new ways.' || char(13) || '
' || char(13) || '
Path of Exile: Keepers of the Flame will launch on October 31 (PDT).', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 1, 0, '[]', 'Art/2DArt/UIImages/Login/LeagueInfo/Keepers/buylarge', 'Play the Keepers of the Flame on October 31st', '[174,130,204]', '', 0, 0),
(339, 24, 'Trailer', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/MirageThumbnailTrailer', '', '[]', '', 0, 'http://web.poecdn.com/public/videos/MirageTrailer_EN.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(340, 24, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/Panel1', '', '[]', 'In Path of Exile: Mirage you will take on a rogue sect of the Faridun as they sap the energies of captured Djinn for nefarious ends, and help a legendary Maraketh Sekhema put an end to an ancient war once and for all.' || char(13) || '
' || char(13) || '
Our new expansion introduces a new Challenge League, a variety of new and reworked Skill and Support Gems, significant Endgame changes and a plethora of Quality of Life features.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Path of Exile: Mirage', '[218,172,69]', '', 0, 0),
(341, 24, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/Panel2', '', '[]', '<italic>{"The Afarud disgust me. They are the pariahs of the outcasts. The violent, the sadists, and the evil. For generations, they have made plague and darkness their tools. They steal what is ours, and commit unspeakable acts..."}' || char(13) || '
- Varashta, the Winter Sekhema' || char(13) || '
' || char(13) || '
The Afarud, the most depraved and twisted of the Faridun, have formed a pact with Saresh, a powerful necromancer who built an army of undead to seek revenge on the Maraketh. They intend to seek out and harness the power of the Djinn, twisting it to their ends to further their war on the Maraketh. Varashta, a powerful Sekhema who has been suspended in time for eons, will assist you as you seek to halt the Afarud''s efforts in Wraeclast.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'The Rejected of the Rejected', '[218,172,69]', '', 0, 0),
(342, 24, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/Panel3', '', '["Art/2DArt/UIImages/Login/LeagueInfo/Mirage/screenshots/Panel3/Screenshot1","Art/2DArt/UIImages/Login/LeagueInfo/Mirage/screenshots/Panel3/Screenshot2","Art/2DArt/UIImages/Login/LeagueInfo/Mirage/screenshots/Panel3/Screenshot3"]', 'In the Mirage Challenge League, you will encounter the souls of Djinn torturously trapped by the Afarud, and work to set them free.' || char(13) || '
' || char(13) || '
To free these trapped souls, you must enter the Mirage they project, an imperfect copy of the area around the captured Djinn. Fight your way through the monsters, astral hazards, and Afarud mages to the tether holding the Djinn. Free them, and you will be rewarded.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'The Mirage Challenge League', '[218,172,69]', '', 0, 0),
(343, 24, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/Panel4', '', '[]', 'Being a Djinn herself, Varashta can offer you a further mote of ancient Maraketh power, providing you with three wishes to choose from. Each of these is a powerful modifier which will augment the Mirage you enter.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Choose Your Wish', '[218,172,69]', '', 0, 0),
(344, 24, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/Panel5', '', '[]', 'The magic of the Mirage will augment any other league mechanic that appears within its dominion. Warped into existence by the Astral realm, these encounters behave differently, and can sometimes provide strange and powerful rewards.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Mirage/EssenceofDesolation.itemblob","Metadata/LeagueInfoPanelItems/Mirage/CrystallisedRancour.itemblob"]', '', 'Empowered Leagues and Rewards', '[218,172,69]', '', 0, 0),
(345, 24, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/Panel6', '', '[]', 'The Afarud are not only torturers but thieves, and have over the centuries stolen away countless priceless Maraketh artefacts - but using their magic, they have twisted and warped these to items suit their own purposes.' || char(13) || '
' || char(13) || '
Use the forbidden power of these desecrated artefacts or restore them to their former glory with the aid of Varashta.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Mirage/KhatalsWeeping.itemblob","Metadata/LeagueInfoPanelItems/Mirage/CoinofRestoration.itemblob","Metadata/LeagueInfoPanelItems/Mirage/KhatalsGeyser.itemblob"]', '', 'Restore Maraketh Artefacts', '[218,172,69]', '', 0, 0),
(346, 24, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/Panel7', '', '[]', 'Slain enemies in Mirages will rarely drop some of the most powerful instruments of Maraketh Magic - Coins of Power, Skill or Knowledge. Each of these can be used on a level 20 Skill Gem, corrupting it and imbuing it with a Level 1 Support effect which will inherently support that Skill.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Mirage/CoinofPower.itemblob","Metadata/LeagueInfoPanelItems/Mirage/GroundSlam.itemblob"]', '', 'Imbue Your Skills', '[218,172,69]', '', 0, 0),
(347, 24, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/Panel8', '', '[]', 'By meddling in the affairs of the Afarud, you will eventually draw the ire of Saresh, the necromancer supreme. Do you dare to face him and put a stop to his marauding undead legion?', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Mirage/TheSandsofTime.itemblob"]', '', 'Saresh, of the Weeping Black', '[218,172,69]', '', 0, 0),
(348, 24, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/Panel9', '', '[]', 'In this expansion, we are adding a variety of new Holy Skill Gems. Slam the ground to call down a hammer of justice, summon forth an army of divine armaments, or project the power of the sun into a blast of righteous anger.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Mirage/HolyHammers.itemblob","Metadata/LeagueInfoPanelItems/Mirage/DivineBlast.itemblob","Metadata/LeagueInfoPanelItems/Mirage/HolySweep.itemblob"]', '', 'The Power of Light', '[218,172,69]', '', 0, 0),
(349, 24, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/Panel10', '', '[]', 'In Path of Exile: Mirage, extensive changes are coming to the Atlas and Mapping systems.' || char(13) || '
' || char(13) || '
Map items no longer require a specific map item to access an associated map area. Instead, you will have a map item of a given tier that can be used to open any map on your Atlas with a tier equal to or lower than the map item tier.' || char(13) || '
' || char(13) || '
You will still be able to choose any map you''d like to access, as you will select through the Atlas Screen which map area you''d like to travel to. The Atlas screen will default to the previously opened map, allowing you to run the same map again with minimal clicking!', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Endgame Revised', '[218,172,69]', '', 0, 0),
(350, 24, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/Panel11', '', '[]', 'The structure of the Atlas has also changed: you will now begin at the centre of the Atlas, with each corner housing one of the four Voidstones, and all content accessed from your map device now exists physically on the Atlas. You will have to explore the Atlas in order to discover where all the feared Atlas entities reside.' || char(13) || '
' || char(13) || '
Many of these Atlas entities now offer Atlas Skill points, allowing you to get more than ever before. Not all Unique Maps are required to obtain all of your Atlas Skill Points - now only requiring completing any 10 to get the maximum number.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Mirage/OppressiveMapTier16.itemblob","Metadata/LeagueInfoPanelItems/Mirage/UntaintedParadise.itemblob"]', '', 'Fractured Atlas', '[218,172,69]', '', 0, 0),
(351, 24, '12', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/Panel12', '', '[]', 'In this expansion, you will continue helping Eagon in his search for Zana. Using Arcane Astrolabes you will uncover Shaped Regions: unstable areas across the Atlas that Eagon must quell to bring him closer to his true target, the Memory Vaults.' || char(13) || '
' || char(13) || '
Shaped Regions apply a baseline effect to every affected map, and each map within the region has a specific completion condition. Whenever you complete a Map within a Shaped Region, every other map in the Shaped Region gains an additional modifier. This makes your maps more and more intense as you progress, with the relevant mechanic getting juiced to the extreme.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Mirage/NamelessAstrolabe.itemblob","Metadata/LeagueInfoPanelItems/Mirage/TemplarAstrolabe.itemblob"]', '', 'Shaped Regions', '[218,172,69]', '', 0, 0),
(352, 24, '13', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/Panel13', '', '[]', 'Once you have successfully fully completed a Shaped Region, Eagon will be able to bring you along to a Memory Vault. There are four Vaults to explore, with each of them holding powerful rewards for you, and scraps of lost knowledge for Eagon.' || char(13) || '
' || char(13) || '
', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Treasures Await', '[218,172,69]', '', 0, 0),
(353, 24, '14', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/Panel14', '', '[]', 'Upon defeating the Endgame Incarnation bosses in Path of Exile: Mirage, powerful new Support Gems will begin dropping from specific Atlas Bosses. These new Support gems are categorised as Exceptional, being a significant expansion of that class of Support gem.' || char(13) || '
' || char(13) || '
Exceptional Support Gems are more transformative, offering an additional way to customise your build in the late game and extending character customisation even further into a build''s life.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Mirage/EclipseSupport.itemblob","Metadata/LeagueInfoPanelItems/Mirage/BloodsoakedBannerSupport.itemblob","Metadata/LeagueInfoPanelItems/Mirage/HextoadSupport.itemblob"]', '', 'Over 40 New Exceptional Support Gems', '[218,172,69]', '', 0, 0),
(354, 24, '15', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/Panel15', '', '[]', 'Alongside the major overhaul, the Endgame is getting some other changes. The way the Voidstones work has been changed, Petal skills have been removed, Scarabs have received a balance pass, and more.' || char(13) || '
' || char(13) || '
Tier 17 Maps have recieved significant changes to better align with their original design. These are now called Nightmare Maps and are now tier 16, with their primary purpose being to obtain Uber Boss Fragments.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Mirage/DecayedVoidstone.itemblob","Metadata/LeagueInfoPanelItems/Mirage/AnarchyScaraboftheExceptional.itemblob","Metadata/LeagueInfoPanelItems/Mirage/GravenTrail.itemblob"]', '', 'Endgame Systems Overhaul', '[218,172,69]', '', 0, 0),
(355, 24, '16', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/Panel16', '', '[]', 'In Path of Exile: Mirage, Ailith and the Monastery of the Keepers replace the old Breach mechanic. Successfully completing Breach encounters grants Hiveblood, which can be used to grow items from the Genesis Tree.' || char(13) || '
' || char(13) || '
In the endgame, this mechanic receives full Scarab and Atlas Tree support, with Notables and Keystones that allow players to control the type of Breach encounter they find in maps, increase difficulty and rewards, and more.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Mirage/BreachScaraboftheMarshal.itemblob","Metadata/LeagueInfoPanelItems/Mirage/BreachScarabofInstability.itemblob","Metadata/LeagueInfoPanelItems/Mirage/FleshofXesht.itemblob","Metadata/LeagueInfoPanelItems/Mirage/HivebornSupport.itemblob"]', '', 'Wield the Flame', '[218,172,69]', '', 0, 0),
(356, 24, '17', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/Panel17', '', '[]', 'This expansion introduces another round of Quality of Life features. You will now be able to favourite trades on the currency exchange, hover over your Asynchronous trade item sale history, and more.' || char(13) || '
' || char(13) || '
In addition, we''ve added over 20+ landmark rooms throughout the Campaign, so keep an eye out for new and unexpected rooms, side passages, chests, and encounters as you progress through Wraeclast!', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Quality of Life Features', '[218,172,69]', '', 0, 0),
(357, 24, 'SupporterPacks', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/Panel18', '', '[]', 'To celebrate the launch of Path of Exile: Mirage, we''re launching two new sets of Supporter Packs: Curator of Wisdom and Iron Incarcerator packs. There are three price points available for each and they feature masses of points and several exclusive microtransactions that visually interact with gameplay in new ways.' || char(13) || '
' || char(13) || '
Play Path of Exile: Mirage for free on March 6 (PST) on all available platforms.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 1, 0, '[]', 'Art/2DArt/UIImages/Login/LeagueInfo/Mirage/buylarge', 'Play Mirage on ' || char(13) || '
 March 6th', '[218,172,69]', '', 0, 0),
(358, 25, 'Trailer', 'Art/2DArt/UIImages/Login/LeagueInfo/Deepwater/DeepwaterThumbnailTrailer', '', '[]', '', 0, 'http://web.poecdn.com/public/videos/AllflameTrailer_EN.bk2', '', 0, 0, '[]', '', '', '[]', '', 0, 0),
(359, 25, '1', 'Art/2DArt/UIImages/Login/LeagueInfo/Deepwater/Panel1', '', '[]', 'Meet Valerie, a dangerous corsair captain who needs your help retrieving long forgotten treasures from the icy depths of Wraeclast''s oceans.' || char(13) || '
' || char(13) || '
Find Charts scattered across Wraeclast, board The Sovereign, and set sail!', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Deepwater/Panel1_SeabedChart.itemblob","Metadata/LeagueInfoPanelItems/Deepwater/Panel1_CoralReedChart.itemblob"]', '', 'Path of Exile: Curse of the Allflame', '[168,187,167]', '', 0, 0),
(360, 25, '2', 'Art/2DArt/UIImages/Login/LeagueInfo/Deepwater/Panel2', '', '[]', 'Dive to the ocean floor where lanterns imbued with the spark of the Allflame will shield you from the crushing waves. Explore and claim what you can while you can! Lost gold, valuable chests, and lurking threats await you...' || char(13) || '
' || char(13) || '
As the lanterns flicker and fade you''ll need to rush back to the safety of the Bathysphere, to escape the clawing creatures that despise the light you bring.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Descend Into the Depths', '[168,187,167]', '', 0, 0),
(361, 25, '3', 'Art/2DArt/UIImages/Login/LeagueInfo/Deepwater/Panel3', '', '[]', 'Once you have charted enough areas, connect them together to create a Voyage - one giant seafloor excursion. Revisit each chart to claim its rewards again, while also amplifying those rewards in several different ways.  Any area you chart reveals a modifier that applies during a Voyage. The edges of the Voyage Board also feature randomised effects that influence adjacent Charts each Voyage, adding extra rewards.  Plan a profitable Voyage with special Charts that lead to rewarding locations on the ocean floor: from chests filled with treasures and sunken Abyssal pits to ancient artifacts waiting to be discovered and brought back to the surface.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Deepwater/Panel3_SeaBlister.itemblob"]', '', 'Chart Your Voyage', '[168,187,167]', '', 0, 100),
(362, 25, '4', 'Art/2DArt/UIImages/Login/LeagueInfo/Deepwater/Panel4', '', '[]', 'Head belowdecks, and you''ll find the heart of the ship at work. Feed it an item, and it will split into a multitude of ghostly outcomes, one of which you can keep for yourself.' || char(13) || '
' || char(13) || '
Find valuable Ducats on the seafloor and use them to warp and twist items in ways not seen in centuries.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Deepwater/Panel4_Ducat.itemblob","Metadata/LeagueInfoPanelItems/Deepwater/Panel4_Belt.itemblob"]', '', 'Allflame Crafting', '[168,187,167]', '', 0, 0),
(363, 25, '5', 'Art/2DArt/UIImages/Login/LeagueInfo/Deepwater/Panel5', '', '[]', 'Keep an eye out for special types of Charts on your travels throughout Wraeclast! You may even find some that lead to notably... unwelcoming waters.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Deepwater/Panel5_BossChart.itemblob","Metadata/LeagueInfoPanelItems/Deepwater/Panel5_StormBlood.itemblob"]', '', 'Survive the Black Current', '[168,187,167]', '', 0, 0),
(364, 25, '6', 'Art/2DArt/UIImages/Login/LeagueInfo/Deepwater/Panel6', '', '[]', 'The Mercenaries of Trarthus are once again roaming Wraeclast, seeking challengers. Defeat one in a duel to claim a powerful item they''re carrying and recruit them as an ally for the rest of the area.' || char(13) || '
' || char(13) || '
In Maps, if you don''t like a Mercenary''s items, you can request a Warrant that summons that specific Mercenary in a future Map with the same skills but a new set of items.' || char(13) || '
' || char(13) || '
As with any past league that we add to the core game, we have added full Atlas Tree and Scarab support for Mercenaries.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Deepwater/Panel6_Warrant.itemblob","Metadata/LeagueInfoPanelItems/Deepwater/Panel6_Scarab.itemblob"]', '', 'Mercenaries Return', '[168,187,167]', '', 0, 0),
(365, 25, '7', 'Art/2DArt/UIImages/Login/LeagueInfo/Deepwater/Panel7', '', '[]', 'In Curse of the Allflame, the Scion is getting a new Ascendancy class, the Luminary.' || char(13) || '
' || char(13) || '
Upon becoming a Luminary, you can permanently hire a Mercenary as an active ally in combat. Unlike regular Mercenaries, Luminary''s hired Mercenaries can have their equipment changed, unlocking countless new build possibilities.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'The Luminary Ascendancy', '[168,187,167]', '', 0, 0),
(366, 25, '8', 'Art/2DArt/UIImages/Login/LeagueInfo/Deepwater/Panel8', '', '[]', 'Abyss has been significantly reworked in Curse of the Allflame. Abyssal cracks are now open, spilling their energy into the surrounding area, influencing nearby enemies. Slay them to draw the attention of Abyssal hordes that emerge from the depths to tear you apart.  There is now much more visceral feedback in the moment-to-moment gameplay of Abyss with audio and visual cues drawing you along. You can gain Abyssal Jewels and Stygian Vises through the Abyss, and this mechanic has also received a complete refresh of Scarabs and passive tree investment.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Deepwater/Panel8_Spinesnatch.itemblob"]', '', 'Abyss Reworked', '[168,187,167]', '', 0, 200),
(367, 25, '9', 'Art/2DArt/UIImages/Login/LeagueInfo/Deepwater/Panel9', '', '[]', 'Legion has received a major reward overhaul. Use the new Enshrouding Crystals on your Unique Armours, then place them in a crystal within the Domain of Timeless Conflict to create a Vestigial Unique Item with powerful modifiers transferred from the Unique you''ve selected. Vestigial Unique Items are exclusive to Legion and replace Incubators.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Deepwater/Panle9_EnshroudingCrystal.itemblob","Metadata/LeagueInfoPanelItems/Deepwater/Panel9_ShavronnesPace.itemblob"]', '', 'Crystallise Your Power', '[168,187,167]', '', 0, 0),
(368, 25, '10', 'Art/2DArt/UIImages/Login/LeagueInfo/Deepwater/Panel10', '', '[]', 'In this expansion, strange locations have begun to manifest across the Atlas. When you complete Maps affected by a Voidstone, there is a chance that an anomaly will appear on the Atlas.' || char(13) || '
' || char(13) || '
Anomalies are areas that can be run once, granting potentially powerful rewards. Examples include Cadiro Perandus, a mysterious trader offering strange curios for your Gold, or a fully revealed Heist Blueprint wing. There are many anomalies to discover, each tied to a specific Atlas quadrant.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Atlas Anomalies', '[168,187,167]', '', 0, 0),
(369, 25, '11', 'Art/2DArt/UIImages/Login/LeagueInfo/Deepwater/Panel11', '', '[]', 'Socket colours will no longer restrict which Skills and Supports you can put in them, allowing any coloured gem to be socketed. ' || char(13) || '
Red, blue, and green sockets still serve a purpose, granting additional quality to gems of the matching colour.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Deepwater/Panel11_ThePariah.itemblob","Metadata/LeagueInfoPanelItems/Deepwater/Panel11_Omen.itemblob","Metadata/LeagueInfoPanelItems/Deepwater/Panel11_AstralPlate.itemblob"]', '', 'Socket Colours Reworked', '[168,187,167]', '', 0, 0),
(370, 25, '12', 'Art/2DArt/UIImages/Login/LeagueInfo/Deepwater/Panel12', '', '[]', 'Spellcasters have received major improvements across the board, particularly for those that cast Spells themselves. We''ve rebalanced existing spells, trying to add more points of difference for spells of different damage types.' || char(13) || '
' || char(13) || '
The Assassin, Inquisitor, and Occultist. Ascendancies all have new or reworked notables supporting Casters.' || char(13) || '
' || char(13) || '
We have also improved caster itemisation, particularly staves, and added new ways to help solve Mana as a caster. Buffs have been applied to several caster Unique Items, and much more.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '[]', '', 'Spellcaster Rebalance', '[168,187,167]', '', 0, 0),
(371, 25, '13', 'Art/2DArt/UIImages/Login/LeagueInfo/Deepwater/Panel13', '', '[]', 'In this expansion, we are adding a new set of Exceptional Skill Gems called Pacts that you can get from Beyond bosses and Lycia in the Forbidden Sanctum. Make a bargain with a powerful Beyond Demon to empower your Spells at the cost of afflicting yourself.' || char(13) || '
' || char(13) || '
In addition we''ve added a new reservation skill for spellcasters using staves called Mana-infused Staff, as well as several new Transfigured Skill Gems.', 0, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 0, 0, '["Metadata/LeagueInfoPanelItems/Deepwater/Panel13_ManaInfusedStaff.itemblob","Metadata/LeagueInfoPanelItems/Deepwater/Panel13_PactOfGhorr.itemblob"]', '', 'New Spellcaster Skills', '[168,187,167]', '', 0, 0),
(372, 25, 'SupporterPacks', 'Art/2DArt/UIImages/Login/LeagueInfo/Deepwater/Panel14', '', '[]', 'To celebrate the launch of Path of Exile: Curse of the Allflame, we''re launching two new sets of Supporter Packs: the Plague and Remidus packs. There are three price points available for each and they feature masses of points and several exclusive microtransactions that visually interact with gameplay in new ways.' || char(13) || '
' || char(13) || '
Play Path of Exile: Curse of the Allflame for free on July 24 (PDT) on all available platforms.', 1, '', 'Art/2DArt/UIImages/Login/LeagueInfo/textbackground', 1, 0, '[]', 'Art/2DArt/UIImages/Login/LeagueInfo/Deepwater/buylarge', 'Play Curse of the Allflame on July 24th', '[168,187,167]', '', 0, 0);
